import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface RubricScore {
  idea: number;        // A. Relevance & central idea
  structure: number;   // B. Structure & paragraphing
  content: number;     // C. Content & details / evidence
  language: number;    // D. Language clarity & accuracy
  voice: number;       // E. Voice, style, and emotional impact
}

export interface EvaluationResult {
  scores: RubricScore;
  totalXp: number;
  feedback: string;
  isDuplicate: boolean;
  bonusApplied: boolean;
}

export interface UserStats {
  totalXp: number;
  level: number;
  prizesWon: string[];
  submissionHistory: string[]; // Hashes of previous submissions
  lastScore: number;
  bonusCharges: number; // For the +10% next 2 essays bonus
}

export interface ChatMessage {
  role: 'user' | 'ai';
  text: string;
}

export enum AppView {
  DASHBOARD = 'DASHBOARD',
  SUBMIT = 'SUBMIT',
  CO_PILOT = 'CO_PILOT',
  RESULT = 'RESULT'
}

import { GoogleGenAI, Type } from "@google/genai";
import { RubricScore } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function evaluateEssay(imageBase64: string): Promise<{
  scores: RubricScore;
  feedback: string;
}> {
  const model = 'gemini-3-pro-preview';

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: imageBase64,
          },
        },
        {
          text: `Evaluate this student essay based on the following rubric. Provide a score from 0-20 for each category (Total 100 points). 
          BE BRUTALLY HONEST with the scores, but provide constructive and encouraging feedback to help the student improve.

          Rubric Categories:
          1. Relevance & Central Idea (Idea)
          2. Structure & Paragraphing (Structure)
          3. Content & Details / Evidence (Content & Evidence)
          4. Language Clarity & Accuracy (Language)
          5. Voice, Style, and Emotional Impact (Voice)

          Return the response in JSON format.`,
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          scores: {
            type: Type.OBJECT,
            properties: {
              idea: { type: Type.NUMBER },
              structure: { type: Type.NUMBER },
              content: { type: Type.NUMBER },
              language: { type: Type.NUMBER },
              voice: { type: Type.NUMBER },
            },
            required: ['idea', 'structure', 'content', 'language', 'voice'],
          },
          feedback: { type: Type.STRING },
        },
        required: ['scores', 'feedback'],
      },
    },
  });

  try {
    const result = JSON.parse(response.text || '{}');
    return result;
  } catch (e) {
    console.error("Failed to parse evaluation response", e);
    throw new Error("Evaluation failed. Please try again.");
  }
}

export async function getCoPilotInspiration(
  chatHistory: { role: 'user' | 'ai'; text: string }[],
  currentPrompt: string
): Promise<string> {
  const model = 'gemini-3-flash-preview';

  const historyParts = chatHistory.map(msg => ({
    text: `${msg.role === 'user' ? 'Student' : 'Assistant'}: ${msg.text}`
  }));

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...historyParts,
        { text: `Student's request: ${currentPrompt}` }
      ]
    },
    config: {
      systemInstruction: `You are a creative writing co-pilot for a student aged 11-16. 
      Your goal is to give inspiration, themes, metaphors, or starting questions. 
      STRICT RULE: Do not give the student direct answers or write the essay for them. 
      If they ask for an answer or a specific paragraph, politely refuse and instead suggest an idea for them to explore.
      Be encouraging and friendly.`
    }
  });

  return response.text || "I'm sorry, I couldn't generate an inspiration right now.";
}

import React, { useState, useEffect, useCallback } from 'react';
import { AppView, UserStats, EvaluationResult, ChatMessage } from './types';
import { evaluateEssay } from './geminiService';
import Dashboard from './components/Dashboard';
import SubmissionForm from './components/SubmissionForm';
import ResultView from './components/ResultView';
import CoPilotChat from './components/CoPilotChat';
import { BookOpen, LayoutDashboard, Send, Sparkles } from 'lucide-react';

const XP_PER_LEVEL = 1000;

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.DASHBOARD);
  const [userStats, setUserStats] = useState<UserStats>(() => {
    const saved = localStorage.getItem('essayquest_stats');
    return saved ? JSON.parse(saved) : {
      totalXp: 0,
      level: 1,
      prizesWon: [],
      submissionHistory: [],
      lastScore: 0,
      bonusCharges: 0
    };
  });

  const [lastEvaluation, setLastEvaluation] = useState<EvaluationResult | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    localStorage.setItem('essayquest_stats', JSON.stringify(userStats));
  }, [userStats]);

  const generatePrizeCode = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = '';
    for (let i = 0; i < 12; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
      if ((i + 1) % 4 === 0 && i !== 11) code += '-';
    }
    return code;
  };

  const handleSubmission = async (imageBase64: string, isCoPilotUsed: boolean) => {
    setIsProcessing(true);
    try {
      // Basic duplicate detection using simple hash (mocked by base64 length for prototype)
      const contentHash = `hash_${imageBase64.length}`;
      const isDuplicate = userStats.submissionHistory.includes(contentHash);

      const evaluation = await evaluateEssay(imageBase64);
      let scoreXp = Object.values(evaluation.scores).reduce((a, b) => a + b, 0);

      // Co-pilot reduction
      if (isCoPilotUsed) scoreXp = Math.floor(scoreXp / 4);

      // First submission floor
      const isFirstSubmission = userStats.submissionHistory.length === 0;
      if (isFirstSubmission && scoreXp < 50) scoreXp = 50;

      // Duplicate check logic
      if (isDuplicate) scoreXp = 0;

      // Bonus logic
      let finalXp = scoreXp;
      const bonusApplied = userStats.bonusCharges > 0 && !isDuplicate;
      if (bonusApplied) {
        finalXp = Math.floor(finalXp * 1.1);
      }

      // Update stats
      const newTotalXp = userStats.totalXp + finalXp;
      const oldLevel = userStats.level;
      const newLevel = Math.floor(newTotalXp / XP_PER_LEVEL) + 1;

      let newPrizes = [...userStats.prizesWon];
      // Prize every 10 levels
      if (Math.floor(newLevel / 10) > Math.floor(oldLevel / 10)) {
        newPrizes.push(generatePrizeCode());
      }

      // Calculate next bonus state
      let newBonusCharges = userStats.bonusCharges > 0 ? userStats.bonusCharges - 1 : 0;
      if (!isDuplicate && !isFirstSubmission && scoreXp > userStats.lastScore) {
        newBonusCharges = 2; // Next 2 essays get +10%
      }

      setUserStats(prev => ({
        ...prev,
        totalXp: newTotalXp,
        level: newLevel,
        prizesWon: newPrizes,
        submissionHistory: isDuplicate ? prev.submissionHistory : [...prev.submissionHistory, contentHash],
        lastScore: isDuplicate ? prev.lastScore : scoreXp,
        bonusCharges: newBonusCharges
      }));

      setLastEvaluation({
        ...evaluation,
        totalXp: finalXp,
        isDuplicate,
        bonusApplied
      });
      setView(AppView.RESULT);
    } catch (error) {
      alert("Error processing your homework. Please check your connection and try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-4xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setView(AppView.DASHBOARD)}>
            <div className="bg-indigo-600 p-2 rounded-xl text-white">
              <BookOpen size={24} />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">EssayQuest</h1>
          </div>

          <nav className="flex gap-4">
            <button 
              onClick={() => setView(AppView.DASHBOARD)}
              className={`flex items-center gap-1 px-3 py-2 rounded-lg text-sm font-semibold transition-all ${view === AppView.DASHBOARD ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500 hover:bg-slate-100'}`}
            >
              <LayoutDashboard size={18} />
              <span className="hidden sm:inline">Dashboard</span>
            </button>
            <button 
              onClick={() => setView(AppView.SUBMIT)}
              className={`flex items-center gap-1 px-3 py-2 rounded-lg text-sm font-semibold transition-all ${view === AppView.SUBMIT ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500 hover:bg-slate-100'}`}
            >
              <Send size={18} />
              <span className="hidden sm:inline">Submit</span>
            </button>
          </nav>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 w-full max-w-4xl mx-auto px-4 py-8">
        {view === AppView.DASHBOARD && (
          <Dashboard stats={userStats} onStart={() => setView(AppView.SUBMIT)} />
        )}

        {view === AppView.SUBMIT && (
          <SubmissionForm 
            isProcessing={isProcessing} 
            onSubmit={handleSubmission} 
            onOpenCoPilot={() => setView(AppView.CO_PILOT)}
          />
        )}

        {view === AppView.CO_PILOT && (
          <CoPilotChat onBack={() => setView(AppView.SUBMIT)} />
        )}

        {view === AppView.RESULT && lastEvaluation && (
          <ResultView 
            result={lastEvaluation} 
            onDone={() => setView(AppView.DASHBOARD)} 
          />
        )}
      </main>

      {/* Footer */}
      <footer className="py-8 text-center text-slate-400 text-sm">
        <p>© 2024 EssayQuest • Evaluation by AI</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Camera, Upload, AlertCircle, Sparkles, X, ChevronRight } from 'lucide-react';

interface SubmissionFormProps {
  isProcessing: boolean;
  onSubmit: (imageBase64: string, isCoPilotUsed: boolean) => void;
  onOpenCoPilot: () => void;
}

const SubmissionForm: React.FC<SubmissionFormProps> = ({ isProcessing, onSubmit, onOpenCoPilot }) => {
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isCoPilotActive, setIsCoPilotActive] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleRemoveImage = () => {
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = () => {
    if (selectedImage) {
      // Remove data:image/jpeg;base64, prefix for the API
      const base64 = selectedImage.split(',')[1];
      onSubmit(base64, isCoPilotActive);
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6 animate-in slide-in-from-bottom duration-500">
      <div className="text-center space-y-2">
        <h2 className="text-3xl font-black text-slate-800">Submit Your Essay</h2>
        <p className="text-slate-500">Take a clear photo of your handwritten composition or upload a file.</p>
      </div>

      <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-6">
        {/* Upload Area */}
        {!selectedImage ? (
          <div 
            onClick={() => fileInputRef.current?.click()}
            className="border-4 border-dashed border-slate-100 rounded-3xl p-12 text-center hover:border-indigo-200 hover:bg-indigo-50/30 transition-all cursor-pointer group"
          >
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*" 
              capture="environment"
              onChange={handleFileChange}
            />
            <div className="bg-slate-50 w-20 h-20 rounded-2xl flex items-center justify-center mx-auto mb-6 group-hover:scale-110 group-hover:bg-white transition-transform shadow-sm">
              <Camera className="text-slate-400 group-hover:text-indigo-600" size={40} />
            </div>
            <p className="text-lg font-bold text-slate-700 mb-1">Upload Homework Photo</p>
            <p className="text-slate-400 text-sm">PNG, JPG up to 10MB</p>
          </div>
        ) : (
          <div className="relative rounded-2xl overflow-hidden border border-slate-200 group">
            <img src={selectedImage} alt="Preview" className="w-full max-h-96 object-contain bg-slate-50" />
            <button 
              onClick={handleRemoveImage}
              className="absolute top-4 right-4 bg-white/90 backdrop-blur p-2 rounded-full shadow-lg hover:bg-white text-slate-600"
            >
              <X size={20} />
            </button>
          </div>
        )}

        {/* Co-Pilot Switch */}
        <div 
          className={`p-6 rounded-2xl border transition-all ${isCoPilotActive ? 'border-indigo-500 bg-indigo-50/50 shadow-inner' : 'border-slate-100 bg-slate-50'}`}
        >
          <div className="flex items-start justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-xl ${isCoPilotActive ? 'bg-indigo-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
                <Sparkles size={24} />
              </div>
              <div>
                <p className="font-bold text-slate-800">Co-Pilot Mode</p>
                <p className="text-xs font-semibold text-slate-500">Get inspiration, but earn 4x less XP.</p>
              </div>
            </div>
            <button 
              onClick={() => setIsCoPilotActive(!isCoPilotActive)}
              className={`w-14 h-8 rounded-full transition-colors relative ${isCoPilotActive ? 'bg-indigo-600' : 'bg-slate-300'}`}
            >
              <div className={`absolute top-1 w-6 h-6 bg-white rounded-full transition-all ${isCoPilotActive ? 'left-7' : 'left-1'}`} />
            </button>
          </div>

          {isCoPilotActive && (
            <div className="mt-4 pt-4 border-t border-indigo-100">
              <button 
                onClick={onOpenCoPilot}
                className="flex items-center gap-2 text-indigo-700 font-bold text-sm hover:underline"
              >
                Open Inspiration Chat <ChevronRight size={16} />
              </button>
            </div>
          )}
        </div>

        {/* Info Card */}
        <div className="flex items-start gap-3 bg-blue-50/50 p-4 rounded-2xl border border-blue-100">
          <AlertCircle className="text-blue-600 mt-0.5" size={20} />
          <p className="text-sm text-blue-700 font-medium">
            Remember: Only essays and compositions are accepted. The AI values structure, clarity, and your unique voice!
          </p>
        </div>

        {/* Submit Action */}
        <button 
          disabled={!selectedImage || isProcessing}
          onClick={handleSubmit}
          className={`w-full py-5 rounded-2xl font-black text-lg shadow-xl transition-all flex items-center justify-center gap-3
            ${!selectedImage || isProcessing 
              ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
              : 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-indigo-100'
            }`}
        >
          {isProcessing ? (
            <>
              <div className="w-6 h-6 border-4 border-white/30 border-t-white rounded-full animate-spin" />
              Evaluating...
            </>
          ) : (
            <>
              <Send size={20} />
              Submit Homework
            </>
          )}
        </button>
      </div>
    </div>
  );
};

export default SubmissionForm;

import React from 'react';
import { EvaluationResult } from '../types';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, ResponsiveContainer } from 'recharts';
import { CheckCircle2, Trophy, ArrowRight, Zap, RefreshCw } from 'lucide-react';

interface ResultViewProps {
  result: EvaluationResult;
  onDone: () => void;
}

const ResultView: React.FC<ResultViewProps> = ({ result, onDone }) => {
  const chartData = [
    { subject: 'Idea', value: result.scores.idea },
    { subject: 'Structure', value: result.scores.structure },
    { subject: 'Content', value: result.scores.content },
    { subject: 'Language', value: result.scores.language },
    { subject: 'Voice', value: result.scores.voice },
  ];

  const totalScore = Object.values(result.scores).reduce((a, b) => a + b, 0);

  return (
    <div className="max-w-3xl mx-auto space-y-8 animate-in zoom-in duration-500">
      <div className="text-center space-y-4">
        <div className="inline-flex items-center justify-center w-20 h-20 bg-emerald-100 text-emerald-600 rounded-3xl mb-2">
          <CheckCircle2 size={48} />
        </div>
        <h2 className="text-4xl font-black text-slate-800">Homework Evaluated!</h2>
        <div className="flex items-center justify-center gap-2">
          <div className="bg-amber-100 text-amber-700 px-4 py-1.5 rounded-full font-black text-sm flex items-center gap-2">
            <Trophy size={16} />
            SCORE: {totalScore}/100
          </div>
          {result.bonusApplied && (
            <div className="bg-indigo-100 text-indigo-700 px-4 py-1.5 rounded-full font-black text-sm flex items-center gap-2">
              <Zap size={16} />
              +10% BONUS
            </div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {/* Radar Chart */}
        <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex flex-col items-center">
          <h3 className="font-bold text-slate-700 mb-4">Rubric Analysis</h3>
          <div className="w-full h-64">
            <ResponsiveContainer width="100%" height="100%">
              <RadarChart cx="50%" cy="50%" outerRadius="80%" data={chartData}>
                <PolarGrid stroke="#e2e8f0" />
                <PolarAngleAxis dataKey="subject" tick={{ fill: '#64748b', fontSize: 12, fontWeight: 600 }} />
                <Radar
                  name="Score"
                  dataKey="value"
                  stroke="#4f46e5"
                  fill="#4f46e5"
                  fillOpacity={0.5}
                />
              </RadarChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-4 grid grid-cols-2 gap-x-8 gap-y-2 text-sm w-full">
            {chartData.map(d => (
              <div key={d.subject} className="flex justify-between border-b border-slate-50 py-1">
                <span className="text-slate-500 font-medium">{d.subject}</span>
                <span className="font-bold text-slate-800">{d.value}/20</span>
              </div>
            ))}
          </div>
        </div>

        {/* XP Gain Card */}
        <div className="bg-indigo-600 p-8 rounded-3xl text-white shadow-xl shadow-indigo-100 flex flex-col justify-center items-center text-center space-y-6">
          <p className="text-indigo-100 font-bold uppercase tracking-widest text-sm">TOTAL XP EARNED</p>
          <div className="text-7xl font-black tabular-nums">+{result.totalXp}</div>
          <div className="bg-white/10 backdrop-blur-md p-4 rounded-2xl border border-white/20 w-full">
            <p className="text-sm italic opacity-90">
              {result.isDuplicate 
                ? "This looks like a repeat submission! No XP added this time." 
                : "Great progress! Keep writing to unlock your next reward."}
            </p>
          </div>
        </div>
      </div>

      {/* Feedback Section */}
      <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-4">
        <h3 className="text-xl font-bold text-slate-800">Teacher's Feedback</h3>
        <div className="prose prose-slate max-w-none text-slate-600 leading-relaxed">
          {result.feedback.split('\n').map((line, i) => (
            <p key={i}>{line}</p>
          ))}
        </div>
      </div>

      <button 
        onClick={onDone}
        className="w-full bg-slate-800 hover:bg-slate-900 text-white font-black text-lg py-5 rounded-2xl flex items-center justify-center gap-3 transition-all"
      >
        BACK TO DASHBOARD
        <ArrowRight size={24} />
      </button>
    </div>
  );
};

export default ResultView;

import React, { useState, useRef, useEffect } from 'react';
import { Send, Sparkles, ArrowLeft, Bot, User } from 'lucide-react';
import { ChatMessage } from '../types';
import { getCoPilotInspiration } from '../geminiService';

interface CoPilotChatProps {
  onBack: () => void;
}

const CoPilotChat: React.FC<CoPilotChatProps> = ({ onBack }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'ai', text: "Hey there! I'm your Co-Pilot. Stuck on your essay? Tell me what your topic is or what's bothering you, and I'll help you find some inspiration!" }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
      const response = await getCoPilotInspiration(messages, userMsg);
      setMessages(prev => [...prev, { role: 'ai', text: response }]);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'ai', text: "Oops, my brain stalled for a second! Can you try asking that again?" }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto h-[600px] flex flex-col bg-white border border-slate-200 rounded-3xl shadow-sm overflow-hidden animate-in fade-in duration-500">
      {/* Header */}
      <div className="bg-slate-50 p-4 border-b border-slate-200 flex items-center justify-between">
        <button onClick={onBack} className="flex items-center gap-2 text-slate-600 hover:text-slate-900 font-bold text-sm">
          <ArrowLeft size={18} />
          BACK TO SUBMISSION
        </button>
        <div className="flex items-center gap-2 bg-indigo-100 px-3 py-1.5 rounded-full text-indigo-700 font-bold text-xs">
          <Sparkles size={14} />
          CO-PILOT ACTIVE
        </div>
      </div>

      {/* Messages */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shrink-0 shadow-sm
              ${msg.role === 'user' ? 'bg-slate-100 text-slate-500' : 'bg-indigo-600 text-white'}`}
            >
              {msg.role === 'user' ? <User size={20} /> : <Bot size={20} />}
            </div>
            <div className={`max-w-[80%] p-4 rounded-2xl text-sm leading-relaxed
              ${msg.role === 'user' ? 'bg-slate-100 text-slate-800 rounded-tr-none' : 'bg-indigo-50 text-indigo-900 rounded-tl-none'}`}
            >
              {msg.text}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex gap-4">
            <div className="w-10 h-10 rounded-2xl flex items-center justify-center bg-indigo-600 text-white shrink-0 shadow-sm animate-pulse">
              <Bot size={20} />
            </div>
