import React, { useState, useRef, useEffect } from 'react';
import { Send, Sparkles, ArrowLeft, Bot, User, PenTool } from 'lucide-react';
import { ChatMessage } from '../types';
import { getCoPilotInspiration } from '../geminiService';
import { marked } from 'marked';

interface CoPilotChatProps {
  topic: string;
  onBack: () => void;
  onSubmitMode: () => void;
}

const CoPilotChat: React.FC<CoPilotChatProps> = ({ topic, onBack, onSubmitMode }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'ai', text: `Hi! I see your topic is "${topic}". I'm here to help you brainstorm. What part are you stuck on?` }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
      const response = await getCoPilotInspiration(messages, userMsg, topic);
      setMessages(prev => [...prev, { role: 'ai', text: response }]);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'ai', text: "Oops, my brain stalled for a second! Can you try asking that again?" }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto flex flex-col h-[700px] bg-white border border-slate-200 rounded-3xl shadow-sm overflow-hidden animate-in fade-in duration-500">
      {/* Header */}
      <div className="bg-slate-50 p-4 border-b border-slate-200 flex items-center justify-between">
        <button onClick={onBack} className="flex items-center gap-2 text-slate-600 hover:text-slate-900 font-bold text-sm">
          <ArrowLeft size={18} />
          BACK
        </button>
        <div className="text-center overflow-hidden whitespace-nowrap px-4">
          <p className="text-[10px] uppercase font-black text-slate-400">Current Topic</p>
          <p className="text-xs font-bold text-slate-600 truncate max-w-[200px]">{topic}</p>
        </div>
        <div className="flex items-center gap-2 bg-indigo-100 px-3 py-1.5 rounded-full text-indigo-700 font-bold text-xs">
          <Sparkles size={14} />
          CO-PILOT
        </div>
      </div>

      {/* Messages */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shrink-0 shadow-sm
              ${msg.role === 'user' ? 'bg-slate-100 text-slate-500' : 'bg-indigo-600 text-white'}`}
            >
              {msg.role === 'user' ? <User size={20} /> : <Bot size={20} />}
            </div>
            <div className={`max-w-[85%] p-4 rounded-2xl text-sm leading-relaxed shadow-sm
              ${msg.role === 'user' ? 'bg-slate-100 text-slate-800 rounded-tr-none' : 'bg-indigo-50 text-indigo-900 rounded-tl-none'}`}
            >
              {msg.role === 'ai' ? (
                <div 
                  className="prose prose-sm prose-indigo max-w-none prose-p:my-1 prose-headings:my-2 prose-ul:my-2 prose-li:my-0.5"
                  dangerouslySetInnerHTML={{ __html: marked.parse(msg.text) as string }} 
                />
              ) : (
                msg.text
              )}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex gap-4">
            <div className="w-10 h-10 rounded-2xl flex items-center justify-center bg-indigo-600 text-white shrink-0 shadow-sm animate-pulse">
              <Bot size={20} />
            </div>
            <div className="bg-indigo-50 p-4 rounded-2xl rounded-tl-none">
              <div className="flex gap-1">
                <div className="w-2 h-2 bg-indigo-300 rounded-full animate-bounce" />
                <div className="w-2 h-2 bg-indigo-300 rounded-full animate-bounce [animation-delay:0.2s]" />
                <div className="w-2 h-2 bg-indigo-300 rounded-full animate-bounce [animation-delay:0.4s]" />
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Input & Call to Action */}
      <div className="p-4 bg-slate-50 border-t border-slate-200 space-y-4">
        <div className="relative">
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Ask for an idea..."
            className="w-full bg-white border border-slate-200 rounded-2xl px-6 py-4 pr-16 focus:outline-none focus:ring-2 focus:ring-indigo-500 font-medium"
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim() || isLoading}
            className={`absolute right-2 top-2 bottom-2 px-4 rounded-xl text-white transition-all
              ${!input.trim() || isLoading ? 'bg-slate-200' : 'bg-indigo-600 hover:bg-indigo-700'}`}
          >
            <Send size={18} />
          </button>
        </div>

        <button 
          onClick={onSubmitMode}
          className="w-full bg-emerald-600 hover:bg-emerald-700 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-2 shadow-lg shadow-emerald-100 transition-all"
        >
          <PenTool size={20} />
          DONE GETTING IDEAS? SUBMIT ESSAY
        </button>
      </div>
    </div>
  );
};

export default CoPilotChat;

import React, { useState, useEffect } from 'react';
import { AppView, UserStats, EvaluationResult } from './types';
import { evaluateEssay } from './geminiService';
import Dashboard from './components/Dashboard';
import SubmissionForm from './components/SubmissionForm';
import ResultView from './components/ResultView';
import CoPilotChat from './components/CoPilotChat';
import { BookOpen, LayoutDashboard, Send } from 'lucide-react';

const XP_PER_LEVEL = 1000;

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.DASHBOARD);
  const [currentTopic, setCurrentTopic] = useState('');
  const [isCoPilotActiveForSubmission, setIsCoPilotActiveForSubmission] = useState(false);

  const [userStats, setUserStats] = useState<UserStats>(() => {
    const saved = localStorage.getItem('essayquest_stats');
    return saved ? JSON.parse(saved) : {
      totalXp: 0,
      level: 1,
      prizesWon: [],
      submissionHistory: [],
      lastScore: 0,
      bonusCharges: 0
    };
  });

  const [lastEvaluation, setLastEvaluation] = useState<EvaluationResult | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    localStorage.setItem('essayquest_stats', JSON.stringify(userStats));
  }, [userStats]);

  const generatePrizeCode = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = '';
    for (let i = 0; i < 12; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
      if ((i + 1) % 4 === 0 && i !== 11) code += '-';
    }
    return code;
  };

  const handleSubmission = async (imageBase64: string) => {
    setIsProcessing(true);
    try {
      const contentHash = `hash_${imageBase64.length}`;
      const isDuplicate = userStats.submissionHistory.includes(contentHash);

      const evaluation = await evaluateEssay(imageBase64, currentTopic);

      let scoreXp = evaluation.scores.idea + evaluation.scores.structure + evaluation.scores.content + evaluation.scores.language + evaluation.scores.voice;

      // Co-pilot reduction (4x less)
      if (isCoPilotActiveForSubmission) {
        scoreXp = Math.floor(scoreXp / 4);
      }

      const isFirstSubmission = userStats.submissionHistory.length === 0;
      if (isFirstSubmission && scoreXp < 50 && scoreXp > 0) scoreXp = 50;
      if (isDuplicate) scoreXp = 0;

      let finalXp = scoreXp;
      const bonusApplied = userStats.bonusCharges > 0 && !isDuplicate && scoreXp > 0;
      if (bonusApplied) {
        finalXp = Math.floor(finalXp * 1.1);
      }

      const newTotalXp = userStats.totalXp + finalXp;
      const oldLevel = userStats.level;
      const newLevel = Math.floor(newTotalXp / XP_PER_LEVEL) + 1;

      let newPrizes = [...userStats.prizesWon];
      if (Math.floor(newLevel / 10) > Math.floor(oldLevel / 10)) {
        newPrizes.push(generatePrizeCode());
      }

      let newBonusCharges = userStats.bonusCharges > 0 ? userStats.bonusCharges - 1 : 0;
      if (!isDuplicate && !isFirstSubmission && scoreXp > userStats.lastScore && scoreXp > 0) {
        newBonusCharges = 2;
      }

      setUserStats(prev => ({
        ...prev,
        totalXp: newTotalXp,
        level: newLevel,
        prizesWon: newPrizes,
        submissionHistory: isDuplicate ? prev.submissionHistory : [...prev.submissionHistory, contentHash],
        lastScore: isDuplicate ? prev.lastScore : scoreXp,
        bonusCharges: newBonusCharges
      }));

      setLastEvaluation({
        ...evaluation,
        totalXp: finalXp,
        isDuplicate,
        bonusApplied
      });
      setView(AppView.RESULT);
      // Reset submission context
      setCurrentTopic('');
      setIsCoPilotActiveForSubmission(false);
    } catch (error) {
      alert("Error processing your homework. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-4xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setView(AppView.DASHBOARD)}>
            <div className="bg-indigo-600 p-2 rounded-xl text-white">
              <BookOpen size={24} />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">EssayQuest</h1>
          </div>

          <nav className="flex gap-4">
            <button 
              onClick={() => setView(AppView.DASHBOARD)}
              className={`flex items-center gap-1 px-3 py-2 rounded-lg text-sm font-semibold transition-all ${view === AppView.DASHBOARD ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500 hover:bg-slate-100'}`}
            >
              <LayoutDashboard size={18} />
              <span className="hidden sm:inline">Dashboard</span>
            </button>
            <button 
              onClick={() => {
                setCurrentTopic('');
                setIsCoPilotActiveForSubmission(false);
                setView(AppView.SUBMIT);
              }}
              className={`flex items-center gap-1 px-3 py-2 rounded-lg text-sm font-semibold transition-all ${view === AppView.SUBMIT ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500 hover:bg-slate-100'}`}
            >
              <Send size={18} />
              <span className="hidden sm:inline">Submit</span>
            </button>
          </nav>
        </div>
      </header>

      <main className="flex-1 w-full max-w-4xl mx-auto px-4 py-8">
        {view === AppView.DASHBOARD && (
          <Dashboard stats={userStats} onStart={() => setView(AppView.SUBMIT)} />
        )}

        {view === AppView.SUBMIT && (
          <SubmissionForm 
            isProcessing={isProcessing} 
            topic={currentTopic}
            setTopic={setCurrentTopic}
            onSubmit={handleSubmission} 
            onOpenCoPilot={() => {
              setIsCoPilotActiveForSubmission(true);
              setView(AppView.CO_PILOT);
            }}
            isCoPilotActive={isCoPilotActiveForSubmission}
          />
        )}

        {view === AppView.CO_PILOT && (
          <CoPilotChat 
            topic={currentTopic}
            onBack={() => setView(AppView.SUBMIT)} 
            onSubmitMode={() => setView(AppView.SUBMIT)}
          />
        )}

        {view === AppView.RESULT && lastEvaluation && (
          <ResultView 
            result={lastEvaluation} 
            onDone={() => setView(AppView.DASHBOARD)} 
          />
        )}
      </main>

      <footer className="py-8 text-center text-slate-400 text-sm">
        <p>© 2024 EssayQuest • Evaluation by AI</p>
      </footer>
    </div>
  );
};

export default App;

