import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RubricScore } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Extracts the assignment topic or instructions from an image.
 */
export async function extractTopicFromImage(imageBase64: string): Promise<string> {
  const model = 'gemini-3-flash-preview';
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: imageBase64,
          },
        },
        {
          text: "Read this homework assignment or essay prompt image. Extract and summarize the main topic or question the student needs to write about. Be concise.",
        },
      ],
    },
  });

  return response.text || "Could not identify topic.";
}

/**
 * Evaluates the handwritten essay image based on the provided topic.
 */
export async function evaluateEssay(imageBase64: string, topic: string): Promise<{
  scores: RubricScore;
  feedback: string;
}> {
  const model = 'gemini-3-pro-preview';

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: imageBase64,
          },
        },
        {
          text: `Evaluate this student's essay submission based on the topic: "${topic}".

          STRICT REQUIREMENTS: 
          1. CONTENT TYPE CHECK: Check if the work is an ESSAY or COMPOSITION. If the image contains something else (e.g., math problems, science diagrams, random drawings, or a list of unrelated words that do not form a story or essay), you MUST give a score of 0 for EVERY category.
          2. HANDWRITING CHECK: Check if the essay in the image is HANDWRITTEN. If the text is TYPED (digital font, printed, or computer-generated text), you MUST give a score of 0 for EVERY category.
          3. If the work IS a handwritten essay/composition, evaluate it honestly using the rubric.

          Rubric (0-20 points each):
          A. Relevance & Central Idea (Idea)
          B. Structure & Paragraphing (Structure)
          C. Content & Details / Evidence (Content & Evidence)
          D. Language Clarity & Accuracy (Language)
          E. Voice, Style, and Emotional Impact (Voice)

          Return the response in JSON format. If you give 0 points due to requirements 1 or 2, explain this clearly in the feedback.`,
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          scores: {
            type: Type.OBJECT,
            properties: {
              idea: { type: Type.NUMBER },
              structure: { type: Type.NUMBER },
              content: { type: Type.NUMBER },
              language: { type: Type.NUMBER },
              voice: { type: Type.NUMBER },
            },
            required: ['idea', 'structure', 'content', 'language', 'voice'],
          },
          feedback: { type: Type.STRING },
        },
        required: ['scores', 'feedback'],
      },
    },
  });

  try {
    const result = JSON.parse(response.text || '{}');
    return result;
  } catch (e) {
    console.error("Failed to parse evaluation response", e);
    throw new Error("Evaluation failed. Please try again.");
  }
}

export async function getCoPilotInspiration(
  chatHistory: { role: 'user' | 'ai'; text: string }[],
  currentPrompt: string,
  topic: string
): Promise<string> {
  const model = 'gemini-3-flash-preview';

  const historyParts = chatHistory.map(msg => ({
    text: `${msg.role === 'user' ? 'Student' : 'Assistant'}: ${msg.text}`
  }));

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...historyParts,
        { text: `Topic of the essay: ${topic}. Student's current request: ${currentPrompt}` }
      ]
    },
    config: {
      systemInstruction: `You are a creative writing co-pilot for a student aged 11-16. 
      The essay topic is: "${topic}".
      Your goal is to give inspiration, themes, metaphors, or starting questions based on this topic. 

      STRICT RULES:
      1. Keep your responses CONCISE and SHORT (aim for under 100 words).
      2. Do not use complex language; be punchy and encouraging.
      3. Use simple Markdown formatting (bullet points, bold text) to make it easy to read.
      4. Do not give the student direct answers or write the essay for them.
      5. If they ask for an answer or a specific paragraph, politely refuse and instead suggest an idea for them to explore.`
    }
  });

  return response.text || "I'm sorry, I couldn't generate an inspiration right now.";
}

/**
 * Spelling Services
 */

export async function extractSpellingList(imageBase64: string): Promise<string[]> {
  const model = 'gemini-3-flash-preview';
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: { mimeType: 'image/jpeg', data: imageBase64 }
        },
        { text: "Extract all the spelling words from this image. Return only the list of words as a JSON array of strings." }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: { type: Type.STRING }
      }
    }
  });

  return JSON.parse(response.text || "[]");
}

export async function generateSpellingAudio(word: string): Promise<string> {
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Say the word clearly: ${word}.` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Audio generation failed");
  return base64Audio;
}

export async function evaluateSpellingAnswers(
  listImageBase64: string,
  answerImageBase64: string,
  words: string[]
): Promise<{
  correctWords: string[];
  incorrectWords: { original: string; student: string }[];
  feedback: string;
}> {
  const model = 'gemini-3-pro-preview';
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { inlineData: { mimeType: 'image/jpeg', data: listImageBase64 } },
        { inlineData: { mimeType: 'image/jpeg', data: answerImageBase64 } },
        { 
          text: `The first image is the master spelling list. The second image is the student's handwritten answers. 
          Check the spelling accuracy for each of these words: ${words.join(', ')}. 
          Be strict with spelling. If a word is handwritten, ensure you read it carefully. 
          Return a JSON object with:
          1. correctWords: Array of strings that the student spelled exactly right.
          2. incorrectWords: Array of objects with 'original' and 'student' (what the student wrote).
          3. feedback: A short encouraging message.`
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          correctWords: { type: Type.ARRAY, items: { type: Type.STRING } },
          incorrectWords: { 
            type: Type.ARRAY, 
            items: { 
              type: Type.OBJECT,
              properties: {
                original: { type: Type.STRING },
                student: { type: Type.STRING }
              }
            }
          },
          feedback: { type: Type.STRING }
        },
        required: ['correctWords', 'incorrectWords', 'feedback']
      }
    }
  });

  return JSON.parse(response.text || "{}");
}

import React, { useState, useEffect } from 'react';
import { AppView, UserStats, EvaluationResult } from './types';
import { evaluateEssay } from './geminiService';
import Dashboard from './components/Dashboard';
import SubmissionForm from './components/SubmissionForm';
import ResultView from './components/ResultView';
import CoPilotChat from './components/CoPilotChat';
import SpellingPractice from './components/SpellingPractice';
import { BookOpen, LayoutDashboard, Send, Mic } from 'lucide-react';

const XP_PER_LEVEL = 1000;

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.DASHBOARD);
  const [currentTopic, setCurrentTopic] = useState('');
  const [isCoPilotActiveForSubmission, setIsCoPilotActiveForSubmission] = useState(false);

  const [userStats, setUserStats] = useState<UserStats>(() => {
    const saved = localStorage.getItem('essayquest_stats');
    return saved ? JSON.parse(saved) : {
      totalXp: 0,
      level: 1,
      prizesWon: [],
      submissionHistory: [],
      lastScore: 0,
      bonusCharges: 0
    };
  });

  const [lastEvaluation, setLastEvaluation] = useState<EvaluationResult | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    localStorage.setItem('essayquest_stats', JSON.stringify(userStats));
  }, [userStats]);

  const generatePrizeCode = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = '';
    for (let i = 0; i < 12; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
      if ((i + 1) % 4 === 0 && i !== 11) code += '-';
    }
    return code;
  };

  const handleSpellingXp = (correctCount: number) => {
    const xpToAdd = correctCount;
    const newTotalXp = userStats.totalXp + xpToAdd;
    const newLevel = Math.floor(newTotalXp / XP_PER_LEVEL) + 1;

    setUserStats(prev => ({
      ...prev,
      totalXp: newTotalXp,
      level: newLevel
    }));
  };

  const handleSubmission = async (imageBase64: string) => {
    setIsProcessing(true);
    try {
      const contentHash = `hash_${imageBase64.length}`;
      const isDuplicate = userStats.submissionHistory.includes(contentHash);

      const evaluation = await evaluateEssay(imageBase64, currentTopic);

      let scoreXp = evaluation.scores.idea + evaluation.scores.structure + evaluation.scores.content + evaluation.scores.language + evaluation.scores.voice;

      // Co-pilot reduction (4x less)
      if (isCoPilotActiveForSubmission) {
        scoreXp = Math.floor(scoreXp / 4);
      }

      const isFirstSubmission = userStats.submissionHistory.length === 0;
      if (isFirstSubmission && scoreXp < 50 && scoreXp > 0) scoreXp = 50;
      if (isDuplicate) scoreXp = 0;

      let finalXp = scoreXp;
      const bonusApplied = userStats.bonusCharges > 0 && !isDuplicate && scoreXp > 0;
      if (bonusApplied) {
        finalXp = Math.floor(finalXp * 1.1);
      }

      const newTotalXp = userStats.totalXp + finalXp;
      const oldLevel = userStats.level;
      const newLevel = Math.floor(newTotalXp / XP_PER_LEVEL) + 1;

      let newPrizes = [...userStats.prizesWon];
      if (Math.floor(newLevel / 10) > Math.floor(oldLevel / 10)) {
        newPrizes.push(generatePrizeCode());
      }

      let newBonusCharges = userStats.bonusCharges > 0 ? userStats.bonusCharges - 1 : 0;
      if (!isDuplicate && !isFirstSubmission && scoreXp > userStats.lastScore && scoreXp > 0) {
        newBonusCharges = 2;
      }

      setUserStats(prev => ({
        ...prev,
        totalXp: newTotalXp,
        level: newLevel,
        prizesWon: newPrizes,
        submissionHistory: isDuplicate ? prev.submissionHistory : [...prev.submissionHistory, contentHash],
        lastScore: isDuplicate ? prev.lastScore : scoreXp,
        bonusCharges: newBonusCharges
      }));

      setLastEvaluation({
        ...evaluation,
        totalXp: finalXp,
        isDuplicate,
        bonusApplied
      });
      setView(AppView.RESULT);
      // Reset submission context
      setCurrentTopic('');
      setIsCoPilotActiveForSubmission(false);
    } catch (error) {
      alert("Error processing your homework. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-4xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setView(AppView.DASHBOARD)}>
            <div className="bg-indigo-600 p-2 rounded-xl text-white">
              <BookOpen size={24} />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">EssayQuest</h1>
          </div>

          <nav className="flex gap-4">
            <button 
              onClick={() => setView(AppView.DASHBOARD)}
              className={`flex items-center gap-1 px-3 py-2 rounded-lg text-sm font-semibold transition-all ${view === AppView.DASHBOARD ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500 hover:bg-slate-100'}`}
            >
              <LayoutDashboard size={18} />
              <span className="hidden sm:inline">Dashboard</span>
            </button>
            <button 
              onClick={() => setView(AppView.SPELLING)}
              className={`flex items-center gap-1 px-3 py-2 rounded-lg text-sm font-semibold transition-all ${view === AppView.SPELLING ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500 hover:bg-slate-100'}`}
            >
              <Mic size={18} />
              <span className="hidden sm:inline">Spelling</span>
            </button>
            <button 
              onClick={() => {
                setCurrentTopic('');
                setIsCoPilotActiveForSubmission(false);
                setView(AppView.SUBMIT);
              }}
              className={`flex items-center gap-1 px-3 py-2 rounded-lg text-sm font-semibold transition-all ${view === AppView.SUBMIT ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500 hover:bg-slate-100'}`}
            >
              <Send size={18} />
              <span className="hidden sm:inline">Submit</span>
            </button>
          </nav>
        </div>
      </header>

      <main className="flex-1 w-full max-w-4xl mx-auto px-4 py-8">
        {view === AppView.DASHBOARD && (
          <Dashboard stats={userStats} onStart={() => setView(AppView.SUBMIT)} onStartSpelling={() => setView(AppView.SPELLING)} />
        )}

        {view === AppView.SUBMIT && (
          <SubmissionForm 
            isProcessing={isProcessing} 
            topic={currentTopic}
            setTopic={setCurrentTopic}
            onSubmit={handleSubmission} 
            onOpenCoPilot={() => {
              setIsCoPilotActiveForSubmission(true);
              setView(AppView.CO_PILOT);
            }}
            isCoPilotActive={isCoPilotActiveForSubmission}
          />
        )}

        {view === AppView.CO_PILOT && (
          <CoPilotChat 
            topic={currentTopic}
            onBack={() => setView(AppView.SUBMIT)} 
            onSubmitMode={() => setView(AppView.SUBMIT)}
          />
        )}

        {view === AppView.SPELLING && (
          <SpellingPractice 
            onXpEarned={handleSpellingXp}
            onDone={() => setView(AppView.DASHBOARD)}
          />
        )}

        {view === AppView.RESULT && lastEvaluation && (
          <ResultView 
            result={lastEvaluation} 
            onDone={() => setView(AppView.DASHBOARD)} 
          />
        )}
      </main>

      <footer className="py-8 text-center text-slate-400 text-sm">
        <p>© 2024 EssayQuest • Evaluation by AI</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Camera, Volume2, SkipForward, RotateCcw, Send, CheckCircle2, Loader2, List, PenTool, ArrowLeft } from 'lucide-react';
import { extractSpellingList, generateSpellingAudio, evaluateSpellingAnswers } from '../geminiService';

interface SpellingPracticeProps {
  onXpEarned: (xp: number) => void;
  onDone: () => void;
}

const SpellingPractice: React.FC<SpellingPracticeProps> = ({ onXpEarned, onDone }) => {
  const [step, setStep] = useState<'UPLOAD_LIST' | 'PRACTICE' | 'UPLOAD_ANSWERS' | 'RESULT'>('UPLOAD_LIST');
  const [words, setWords] = useState<string[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [listImage, setListImage] = useState<string | null>(null);
  const [answerImage, setAnswerImage] = useState<string | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  const [result, setResult] = useState<{
    correctWords: string[];
    incorrectWords: { original: string; student: string }[];
    feedback: string;
  } | null>(null);

  const listInputRef = useRef<HTMLInputElement>(null);
  const answerInputRef = useRef<HTMLInputElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Handle List Upload
  const handleListUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsProcessing(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setListImage(base64);
        try {
          const extracted = await extractSpellingList(base64.split(',')[1]);
          if (extracted.length === 0) throw new Error("No words found");
          setWords(extracted);
          setStep('PRACTICE');
        } catch (err) {
          alert("Couldn't read the spelling list. Try a clearer photo!");
        } finally {
          setIsProcessing(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  // Handle Audio Generation
  const fetchAudio = async (word: string) => {
    setIsPlaying(true);
    try {
      const base64 = await generateSpellingAudio(word);
      const blob = await (await fetch(`data:audio/pcm;base64,${base64}`)).blob();

      // We need to wrap raw PCM in a WAV header or just use the base64 properly.
      // Since generateSpellingAudio follows the spec, we'll use AudioContext for raw PCM if needed, 
      // but for simplicity here we'll assume a standard base64 audio URI works if the API returns a compatible format.
      // If it's raw PCM, we'd use the decodeAudioData utility.

      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      const binaryString = atob(base64);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);

      const dataInt16 = new Int16Array(bytes.buffer);
      const frameCount = dataInt16.length;
      const buffer = audioCtx.createBuffer(1, frameCount, 24000);
      const channelData = buffer.getChannelData(0);
      for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i] / 32768.0;

      const source = audioCtx.createBufferSource();
      source.buffer = buffer;
      source.connect(audioCtx.destination);
      source.onended = () => setIsPlaying(false);
      source.start();
    } catch (err) {
      console.error(err);
      setIsPlaying(false);
    }
  };

  const handleNextWord = () => {
    if (currentIndex < words.length - 1) {
      setCurrentIndex(prev => prev + 1);
      setAudioUrl(null);
    } else {
      setStep('UPLOAD_ANSWERS');
    }
  };

  const handleAnswerUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsProcessing(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setAnswerImage(base64);
        try {
          const evalResult = await evaluateSpellingAnswers(
            listImage!.split(',')[1],
            base64.split(',')[1],
            words
          );
          setResult(evalResult);
          onXpEarned(evalResult.correctWords.length);
          setStep('RESULT');
        } catch (err) {
          alert("Error checking answers. Please try again.");
        } finally {
          setIsProcessing(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-8 animate-in fade-in duration-500">
      {/* Step 1: Upload List */}
      {step === 'UPLOAD_LIST' && (
        <div className="text-center space-y-6">
          <div className="bg-emerald-100 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto text-emerald-600">
            <List size={40} />
          </div>
          <div className="space-y-2">
            <h2 className="text-3xl font-black text-slate-800">Spelling Prep</h2>
            <p className="text-slate-500">Upload your spelling list. I'll read the words to you!</p>
          </div>
          <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
            <div 
              onClick={() => listInputRef.current?.click()}
              className="border-4 border-dashed border-slate-100 rounded-3xl p-12 text-center hover:border-emerald-200 hover:bg-emerald-50/30 transition-all cursor-pointer group"
            >
              <input type="file" ref={listInputRef} className="hidden" accept="image/*" onChange={handleListUpload} />
              {isProcessing ? (
                <div className="flex flex-col items-center gap-4">
                  <Loader2 className="animate-spin text-emerald-600" size={40} />
                  <p className="font-bold text-slate-700">Reading your list...</p>
                </div>
              ) : (
                <>
                  <Camera className="text-slate-400 group-hover:text-emerald-600 mx-auto mb-4" size={48} />
                  <p className="text-lg font-bold text-slate-700">Snap Spelling List</p>
                </>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Step 2: Practice Session */}
      {step === 'PRACTICE' && (
        <div className="space-y-8">
          <div className="flex justify-between items-center">
            <button onClick={onDone} className="text-slate-400 hover:text-slate-600 font-bold flex items-center gap-2">
              <ArrowLeft size={20} /> QUIT
            </button>
            <div className="bg-indigo-100 px-4 py-1.5 rounded-full text-indigo-700 font-black text-sm">
              WORD {currentIndex + 1} OF {words.length}
            </div>
          </div>

          <div className="bg-white p-12 rounded-[40px] border border-slate-200 shadow-xl text-center space-y-8">
            <div className="w-32 h-32 bg-indigo-600 rounded-full flex items-center justify-center mx-auto shadow-lg shadow-indigo-200 animate-pulse">
              <Volume2 size={64} className="text-white" />
            </div>

            <div className="space-y-2">
              <h3 className="text-2xl font-black text-slate-800">Listen Carefully</h3>
              <p className="text-slate-500 font-medium italic">Write down what you hear...</p>
            </div>

            <div className="flex justify-center gap-4">
              <button 
                onClick={() => fetchAudio(words[currentIndex])}
                disabled={isPlaying}
                className="bg-slate-100 hover:bg-slate-200 p-6 rounded-3xl transition-all text-slate-700 flex items-center gap-3 font-bold"
              >
                <RotateCcw size={24} /> REPEAT
              </button>
              <button 
                onClick={() => fetchAudio(words[currentIndex])}
                disabled={isPlaying}
                className="bg-indigo-600 hover:bg-indigo-700 p-6 rounded-3xl transition-all text-white flex items-center gap-3 font-bold shadow-lg shadow-indigo-100"
              >
                <Volume2 size={24} /> PLAY
              </button>
            </div>
          </div>

          <button 
            onClick={handleNextWord}
            className="w-full bg-emerald-600 hover:bg-emerald-700 text-white py-6 rounded-3xl font-black text-xl shadow-lg shadow-emerald-100 transition-all flex items-center justify-center gap-3"
          >
            {currentIndex === words.length - 1 ? "I'M FINISHED!" : "NEXT WORD"}
            <SkipForward size={24} />
          </button>
        </div>
      )}

      {/* Step 3: Upload Answers */}
      {step === 'UPLOAD_ANSWERS' && (
        <div className="text-center space-y-6">
          <div className="bg-indigo-100 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto text-indigo-600">
            <PenTool size={40} />
          </div>
          <div className="space-y-2">
            <h2 className="text-3xl font-black text-slate-800">Great Job!</h2>
            <p className="text-slate-500">Now, take a photo of your written answers to see how you did.</p>
          </div>
          <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
            <div 
              onClick={() => answerInputRef.current?.click()}
              className="border-4 border-dashed border-slate-100 rounded-3xl p-12 text-center hover:border-indigo-200 hover:bg-indigo-50/30 transition-all cursor-pointer group"
            >
              <input type="file" ref={answerInputRef} className="hidden" accept="image/*" onChange={handleAnswerUpload} />
              {isProcessing ? (
                <div className="flex flex-col items-center gap-4">
                  <Loader2 className="animate-spin text-indigo-600" size={40} />
                  <p className="font-bold text-slate-700">Checking your spelling...</p>
                </div>
              ) : (
                <>
                  <Camera className="text-slate-400 group-hover:text-indigo-600 mx-auto mb-4" size={48} />
                  <p className="text-lg font-bold text-slate-700">Snap Your Work</p>
                </>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Step 4: Result */}
      {step === 'RESULT' && result && (
        <div className="space-y-8 animate-in zoom-in duration-500">
          <div className="text-center space-y-4">
            <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-3xl flex items-center justify-center mx-auto">
              <CheckCircle2 size={48} />
            </div>
            <h2 className="text-4xl font-black text-slate-800">Spelling Check Done!</h2>
            <div className="text-6xl font-black text-emerald-600">+{result.correctWords.length} XP</div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-200 space-y-4">
              <h3 className="font-bold text-emerald-600 flex items-center gap-2">
                <CheckCircle2 size={18} /> Correct Words
              </h3>
              <div className="flex flex-wrap gap-2">
                {result.correctWords.map(w => (
                  <span key={w} className="bg-emerald-50 text-emerald-700 px-3 py-1 rounded-full font-bold text-sm">
                    {w}
                  </span>
                ))}
                {result.correctWords.length === 0 && <p className="text-slate-400 italic text-sm">No words were correct.</p>}
              </div>
            </div>

            <div className="bg-white p-6 rounded-3xl border border-slate-200 space-y-4">
              <h3 className="font-bold text-red-500 flex items-center gap-2">
                <RotateCcw size={18} /> Needs Practice
              </h3>
              <div className="space-y-2">
                {result.incorrectWords.map((w, i) => (
                  <div key={i} className="flex justify-between text-sm items-center bg-red-50 p-2 rounded-xl">
                    <span className="font-black text-red-700">{w.original}</span>
                    <span className="text-slate-400">→</span>
                    <span className="font-bold text-slate-500">{w.student || "(missing)"}</span>
                  </div>
                ))}
                {result.incorrectWords.length === 0 && <p className="text-slate-400 italic text-sm">Perfect score!</p>}
              </div>
            </div>
          </div>

          <div className="bg-indigo-50 p-6 rounded-3xl border border-indigo-100 text-indigo-900 italic text-center font-medium">
            "{result.feedback}"
          </div>

          <button 
            onClick={onDone}
            className="w-full bg-slate-800 hover:bg-slate-900 text-white font-black text-lg py-5 rounded-2xl transition-all"
          >
            BACK TO DASHBOARD
          </button>
        </div>
      )}
    </div>
  );
};

export default SpellingPractice;

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RubricScore } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Extracts the assignment topic or instructions from an image.
 */
export async function extractTopicFromImage(imageBase64: string): Promise<string> {
  const model = 'gemini-3-flash-preview';
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: imageBase64,
          },
        },
        {
          text: "Read this homework assignment or essay prompt image. Extract and summarize the main topic or question the student needs to write about. Be concise.",
        },
      ],
    },
  });

  return response.text || "Could not identify topic.";
}

/**
 * Evaluates the handwritten essay image based on the provided topic.
 */
export async function evaluateEssay(imageBase64: string, topic: string): Promise<{
  scores: RubricScore;
  feedback: string;
}> {
  const model = 'gemini-3-pro-preview';

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: imageBase64,
          },
        },
        {
          text: `Evaluate this student's essay submission based on the topic: "${topic}".

          STRICT REQUIREMENTS: 
          1. CONTENT TYPE CHECK: Check if the work is an ESSAY or COMPOSITION. If the image contains something else (e.g., math problems, science diagrams, random drawings, or a list of unrelated words that do not form a story or essay), you MUST give a score of 0 for EVERY category.
          2. HANDWRITING CHECK: Check if the essay in the image is HANDWRITTEN. If the text is TYPED (digital font, printed, or computer-generated text), you MUST give a score of 0 for EVERY category.
          3. If the work IS a handwritten essay/composition, evaluate it honestly using the rubric.

          Rubric (0-20 points each):
          A. Relevance & Central Idea (Idea)
          B. Structure & Paragraphing (Structure)
          C. Content & Details / Evidence (Content & Evidence)
          D. Language Clarity & Accuracy (Language)
          E. Voice, Style, and Emotional Impact (Voice)

          Return the response in JSON format. If you give 0 points due to requirements 1 or 2, explain this clearly in the feedback.`,
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          scores: {
            type: Type.OBJECT,
            properties: {
              idea: { type: Type.NUMBER },
              structure: { type: Type.NUMBER },
              content: { type: Type.NUMBER },
              language: { type: Type.NUMBER },
              voice: { type: Type.NUMBER },
            },
            required: ['idea', 'structure', 'content', 'language', 'voice'],
          },
          feedback: { type: Type.STRING },
        },
        required: ['scores', 'feedback'],
      },
    },
  });

  try {
    const result = JSON.parse(response.text || '{}');
    return result;
  } catch (e) {
    console.error("Failed to parse evaluation response", e);
    throw new Error("Evaluation failed. Please try again.");
  }
}

export async function getCoPilotInspiration(
