export async function extractSpellingList(imagesBase64: string[]): Promise<string[]> {
  const model = 'gemini-3-flash-preview';

  const imageParts = imagesBase64.map(data => ({
    inlineData: { mimeType: 'image/jpeg', data }
  }));

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...imageParts,
        { text: "Extract all the unique spelling words from these images. Return only the list of words as a JSON array of strings. Do not include duplicates if the same word appears in multiple images." }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: { type: Type.STRING }
      }
    }
  });

  return JSON.parse(response.text || "[]");
}

export async function generateSpellingAudio(word: string): Promise<string> {
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Clearly say the word: ${word}. Repeat it once slowly.` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Audio generation failed");
  return base64Audio;
}

export async function evaluateSpellingAnswers(
  listImagesBase64: string[],
  answerImageBase64: string,
  words: string[]
): Promise<{
  correctWords: string[];
  incorrectWords: { original: string; student: string }[];
  feedback: string;
}> {
  const model = 'gemini-3-pro-preview';

  const masterListParts = listImagesBase64.map(data => ({
    inlineData: { mimeType: 'image/jpeg', data }
  }));

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...masterListParts,
        { inlineData: { mimeType: 'image/jpeg', data: answerImageBase64 } },
        { 
          text: `The first set of images are the master spelling lists. The final image is the student's handwritten answers. 
          Check the spelling accuracy for each of these words: ${words.join(', ')}. 
          Be strict with spelling. Read the student's handwriting carefully. 
          Return a JSON object with:
          1. correctWords: Array of strings that the student spelled exactly right.
          2. incorrectWords: Array of objects with 'original' and 'student' (what the student wrote).
          3. feedback: A short encouraging message.`
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          correctWords: { type: Type.ARRAY, items: { type: Type.STRING } },
          incorrectWords: { 
            type: Type.ARRAY, 
            items: { 
              type: Type.OBJECT,
              properties: {
                original: { type: Type.STRING },
                student: { type: Type.STRING }
              }
            }
          },
          feedback: { type: Type.STRING }
        },
        required: ['correctWords', 'incorrectWords', 'feedback']
      }
    }
  });

  return JSON.parse(response.text || "{}");
}

import React, { useState, useRef, useEffect } from 'react';
import { Camera, Volume2, SkipForward, RotateCcw, Send, CheckCircle2, Loader2, List, PenTool, ArrowLeft, X, Plus } from 'lucide-react';
