interface SpellingPracticeProps {
  onXpEarned: (xp: number) => void;
  onDone: () => void;
}

// Utility to decode raw PCM from base64 (following SDK guidelines)
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const SpellingPractice: React.FC<SpellingPracticeProps> = ({ onXpEarned, onDone }) => {
  const [step, setStep] = useState<'UPLOAD_LIST' | 'PRACTICE' | 'UPLOAD_ANSWERS' | 'RESULT'>('UPLOAD_LIST');
  const [words, setWords] = useState<string[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);

  // Multiple list images support
  const [listImages, setListImages] = useState<string[]>([]);
  const [answerImage, setAnswerImage] = useState<string | null>(null);

  const [isPlaying, setIsPlaying] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);

  const [result, setResult] = useState<{
    correctWords: string[];
    incorrectWords: { original: string; student: string }[];
    feedback: string;
  } | null>(null);

  const listInputRef = useRef<HTMLInputElement>(null);
  const answerInputRef = useRef<HTMLInputElement>(null);

  // Initialize AudioContext on first interaction to avoid browser blocks
  const initAudio = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    if (audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }
    return audioContextRef.current;
  };

  const handleListPhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setListImages(prev => [...prev, reader.result as string]);
      };
      reader.readAsDataURL(file);
    }
    // Clear input so same file can be picked again if needed
    e.target.value = '';
  };

  const removeListImage = (index: number) => {
    setListImages(prev => prev.filter((_, i) => i !== index));
  };

  const processList = async () => {
    if (listImages.length === 0) return;
    setIsProcessing(true);
    try {
      const base64Array = listImages.map(img => img.split(',')[1]);
      const extracted = await extractSpellingList(base64Array);
      if (extracted.length === 0) throw new Error("No words found");
      setWords(extracted);
      setStep('PRACTICE');
    } catch (err) {
      alert("Couldn't read the spelling list. Try clearer photos!");
    } finally {
      setIsProcessing(false);
    }
  };

  // Handle Audio Generation and Playback
  const playWord = async (word: string) => {
    if (isPlaying) return;
    const ctx = initAudio();
    setIsPlaying(true);

    try {
      const base64 = await generateSpellingAudio(word);
      const audioBytes = decodeBase64(base64);
      const audioBuffer = await decodeAudioData(audioBytes, ctx, 24000, 1);

      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.onended = () => setIsPlaying(false);
      source.start();
    } catch (err) {
      console.error("Playback error:", err);
      setIsPlaying(false);
      alert("Audio failed to play. Please check your connection.");
    }
  };

  const handleNextWord = () => {
    if (currentIndex < words.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      setStep('UPLOAD_ANSWERS');
    }
  };

  const handleAnswerUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsProcessing(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        setAnswerImage(base64);
        try {
          const listBase64s = listImages.map(img => img.split(',')[1]);
          const evalResult = await evaluateSpellingAnswers(
            listBase64s,
            base64.split(',')[1],
            words
          );
          setResult(evalResult);
          onXpEarned(evalResult.correctWords.length);
          setStep('RESULT');
        } catch (err) {
          alert("Error checking answers. Please try again.");
        } finally {
          setIsProcessing(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-8 animate-in fade-in duration-500">
      {/* Step 1: Upload List(s) */}
      {step === 'UPLOAD_LIST' && (
        <div className="text-center space-y-6">
          <div className="bg-emerald-100 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto text-emerald-600">
            <List size={40} />
          </div>
          <div className="space-y-2">
            <h2 className="text-3xl font-black text-slate-800">Spelling Prep</h2>
            <p className="text-slate-500">Upload your spelling list. You can add multiple photos!</p>
          </div>

          <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-6">
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
              {listImages.map((img, i) => (
                <div key={i} className="relative aspect-[3/4] rounded-2xl overflow-hidden border border-slate-200 bg-slate-50 group">
                  <img src={img} alt={`List ${i+1}`} className="w-full h-full object-cover" />
                  <button 
                    onClick={() => removeListImage(i)}
                    className="absolute top-2 right-2 bg-red-500 text-white p-1.5 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <X size={14} />
                  </button>
                </div>
              ))}

              <button 
                onClick={() => listInputRef.current?.click()}
                className="aspect-[3/4] border-4 border-dashed border-slate-100 rounded-2xl flex flex-col items-center justify-center text-slate-400 hover:border-emerald-200 hover:bg-emerald-50/30 transition-all group"
              >
                <Plus size={32} className="group-hover:scale-110 transition-transform" />
                <span className="text-xs font-black mt-2">ADD PHOTO</span>
              </button>
            </div>

            <input type="file" ref={listInputRef} className="hidden" accept="image/*" onChange={handleListPhotoChange} />

            <button 
              disabled={listImages.length === 0 || isProcessing}
              onClick={processList}
              className={`w-full py-5 rounded-2xl font-black text-lg shadow-xl transition-all flex items-center justify-center gap-3
                ${listImages.length === 0 || isProcessing ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : 'bg-emerald-600 hover:bg-emerald-700 text-white shadow-emerald-100'}
              `}
            >
              {isProcessing ? (
                <><Loader2 className="animate-spin" size={20} /> Analyzing Photos...</>
              ) : (
                <><Send size={20} /> Start Practice Session</>
              )}
            </button>
          </div>
        </div>
      )}

      {/* Step 2: Practice Session */}
      {step === 'PRACTICE' && (
        <div className="space-y-8">
          <div className="flex justify-between items-center">
            <button onClick={onDone} className="text-slate-400 hover:text-slate-600 font-bold flex items-center gap-2">
              <ArrowLeft size={20} /> QUIT
            </button>
            <div className="bg-indigo-100 px-4 py-1.5 rounded-full text-indigo-700 font-black text-sm">
              WORD {currentIndex + 1} OF {words.length}
            </div>
          </div>

          <div className="bg-white p-12 rounded-[40px] border border-slate-200 shadow-xl text-center space-y-8">
            <div className={`w-32 h-32 rounded-full flex items-center justify-center mx-auto shadow-lg transition-all duration-300
              ${isPlaying ? 'bg-emerald-500 shadow-emerald-200 scale-110 animate-pulse' : 'bg-indigo-600 shadow-indigo-200'}`}
            >
              <Volume2 size={64} className="text-white" />
            </div>

            <div className="space-y-2">
              <h3 className="text-2xl font-black text-slate-800">Listen Carefully</h3>
              <p className="text-slate-500 font-medium italic">Write down what you hear...</p>
            </div>

            <div className="flex justify-center gap-4">
              <button 
                onClick={() => playWord(words[currentIndex])}
                disabled={isPlaying}
                className="bg-slate-100 hover:bg-slate-200 p-6 rounded-3xl transition-all text-slate-700 flex items-center gap-3 font-bold disabled:opacity-50"
              >
                <RotateCcw size={24} /> REPEAT
              </button>
              <button 
                onClick={() => playWord(words[currentIndex])}
                disabled={isPlaying}
                className="bg-indigo-600 hover:bg-indigo-700 p-6 rounded-3xl transition-all text-white flex items-center gap-3 font-bold shadow-lg shadow-indigo-100 disabled:opacity-50"
              >
                <Volume2 size={24} /> PLAY
              </button>
            </div>
          </div>

          <button 
            onClick={handleNextWord}
            className="w-full bg-emerald-600 hover:bg-emerald-700 text-white py-6 rounded-3xl font-black text-xl shadow-lg shadow-emerald-100 transition-all flex items-center justify-center gap-3"
          >
            {currentIndex === words.length - 1 ? "I'M FINISHED!" : "NEXT WORD"}
            <SkipForward size={24} />
          </button>
        </div>
      )}

      {/* Step 3: Upload Answers */}
      {step === 'UPLOAD_ANSWERS' && (
        <div className="text-center space-y-6">
          <div className="bg-indigo-100 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto text-indigo-600">
            <PenTool size={40} />
          </div>
          <div className="space-y-2">
            <h2 className="text-3xl font-black text-slate-800">Great Job!</h2>
            <p className="text-slate-500">Now, take a photo of your written answers to see how you did.</p>
          </div>
          <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
            <div 
              onClick={() => answerInputRef.current?.click()}
              className="border-4 border-dashed border-slate-100 rounded-3xl p-12 text-center hover:border-indigo-200 hover:bg-indigo-50/30 transition-all cursor-pointer group"
            >
              <input type="file" ref={answerInputRef} className="hidden" accept="image/*" onChange={handleAnswerUpload} />
              {isProcessing ? (
                <div className="flex flex-col items-center gap-4">
                  <Loader2 className="animate-spin text-indigo-600" size={40} />
                  <p className="font-bold text-slate-700">Checking your spelling...</p>
                </div>
              ) : (
                <>
                  <Camera className="text-slate-400 group-hover:text-indigo-600 mx-auto mb-4" size={48} />
                  <p className="text-lg font-bold text-slate-700">Snap Your Work</p>
                </>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Step 4: Result */}
      {step === 'RESULT' && result && (
        <div className="space-y-8 animate-in zoom-in duration-500">
          <div className="text-center space-y-4">
            <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-3xl flex items-center justify-center mx-auto">
              <CheckCircle2 size={48} />
            </div>
            <h2 className="text-4xl font-black text-slate-800">Spelling Check Done!</h2>
            <div className="text-6xl font-black text-emerald-600">+{result.correctWords.length} XP</div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-200 space-y-4">
              <h3 className="font-bold text-emerald-600 flex items-center gap-2">
                <CheckCircle2 size={18} /> Correct Words
              </h3>
              <div className="flex flex-wrap gap-2">
                {result.correctWords.map(w => (
                  <span key={w} className="bg-emerald-50 text-emerald-700 px-3 py-1 rounded-full font-bold text-sm">
                    {w}
                  </span>
                ))}
                {result.correctWords.length === 0 && <p className="text-slate-400 italic text-sm">No words were correct.</p>}
              </div>
            </div>

            <div className="bg-white p-6 rounded-3xl border border-slate-200 space-y-4">
              <h3 className="font-bold text-red-500 flex items-center gap-2">
                <RotateCcw size={18} /> Needs Practice
              </h3>
              <div className="space-y-2">
                {result.incorrectWords.map((w, i) => (
                  <div key={i} className="flex justify-between text-sm items-center bg-red-50 p-2 rounded-xl">
                    <span className="font-black text-red-700">{w.original}</span>
                    <span className="text-slate-400">→</span>
                    <span className="font-bold text-slate-500">{w.student || "(missing)"}</span>
                  </div>
                ))}
                {result.incorrectWords.length === 0 && <p className="text-slate-400 italic text-sm">Perfect score!</p>}
              </div>
            </div>
          </div>

          <div className="bg-indigo-50 p-6 rounded-3xl border border-indigo-100 text-indigo-900 italic text-center font-medium">
            "{result.feedback}"
          </div>

          <button 
            onClick={onDone}
            className="w-full bg-slate-800 hover:bg-slate-900 text-white font-black text-lg py-5 rounded-2xl transition-all"
          >
            BACK TO DASHBOARD
          </button>
        </div>
      )}
    </div>
  );
};

