import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RubricScore } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Extracts the assignment topic or instructions from an image.
 */
export async function extractTopicFromImage(imageBase64: string): Promise<string> {
  const model = 'gemini-3-flash-preview';
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: imageBase64,
          },
        },
        {
          text: "Read this homework assignment or essay prompt image. Extract and summarize the main topic or question the student needs to write about. Be concise.",
        },
      ],
    },
  });

  return response.text || "Could not identify topic.";
}

/**
 * Evaluates the handwritten essay image based on the provided topic.
 */
export async function evaluateEssay(imageBase64: string, topic: string): Promise<{
  scores: RubricScore;
  feedback: string;
}> {
  const model = 'gemini-3-pro-preview';

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: imageBase64,
          },
        },
        {
          text: `Evaluate this student's essay submission based on the topic: "${topic}".

          Rubric (0-20 points each):
          A. Relevance & Central Idea (Idea)
          B. Structure & Paragraphing (Structure)
          C. Content & Details / Evidence (Content & Evidence)
          D. Language Clarity & Accuracy (Language)
          E. Voice, Style, and Emotional Impact (Voice)

          Return JSON format.`,
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          scores: {
            type: Type.OBJECT,
            properties: {
              idea: { type: Type.NUMBER },
              structure: { type: Type.NUMBER },
              content: { type: Type.NUMBER },
              language: { type: Type.NUMBER },
              voice: { type: Type.NUMBER },
            },
            required: ['idea', 'structure', 'content', 'language', 'voice'],
          },
          feedback: { type: Type.STRING },
        },
        required: ['scores', 'feedback'],
      },
    },
  });

  return JSON.parse(response.text || '{}');
}

export async function getCoPilotInspiration(
  chatHistory: { role: 'user' | 'ai'; text: string }[],
  currentPrompt: string,
  topic: string
): Promise<string> {
  const model = 'gemini-3-flash-preview';
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...chatHistory.map(msg => ({ text: `${msg.role}: ${msg.text}` })),
        { text: `Topic: ${topic}. Request: ${currentPrompt}` }
      ]
    },
    config: {
      systemInstruction: `Writer co-pilot. Topic: "${topic}". Be concise.`
    }
  });
  return response.text || "I'm sorry, I couldn't help right now.";
}

/**
 * Spelling Services
 */

export async function extractSpellingList(imagesBase64: string[]): Promise<string[]> {
  const model = 'gemini-3-flash-preview';
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...imagesBase64.map(data => ({ inlineData: { mimeType: 'image/jpeg', data } })),
        { text: "Extract unique spelling words. Return a JSON array of strings." }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: { type: Type.ARRAY, items: { type: Type.STRING } }
    }
  });
  return JSON.parse(response.text || "[]");
}

export async function generateSpellingAudio(word: string): Promise<string> {
  // Enhanced prompt to ensure the model handles Chinese characters as words to be spoken
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Say the following word clearly: ${word}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' },
        },
      },
    },
  });

  const audioPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
  const base64Audio = audioPart?.inlineData?.data;

  if (!base64Audio) throw new Error("Audio generation failed");
  return base64Audio;
}

export async function evaluateSpellingAnswers(
  listImagesBase64: string[],
  answerImageBase64: string,
  words: string[]
): Promise<{
  correctWords: string[];
  incorrectWords: { original: string; student: string }[];
  feedback: string;
}> {
  const model = 'gemini-3-pro-preview';
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...listImagesBase64.map(data => ({ inlineData: { mimeType: 'image/jpeg', data } })),
        { inlineData: { mimeType: 'image/jpeg', data: answerImageBase64 } },
        { text: `Check spelling for: ${words.join(', ')}. Return JSON.` }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          correctWords: { type: Type.ARRAY, items: { type: Type.STRING } },
          incorrectWords: { 
            type: Type.ARRAY, 
            items: { 
              type: Type.OBJECT,
              properties: {
                original: { type: Type.STRING },
                student: { type: Type.STRING }
              }
            }
          },
          feedback: { type: Type.STRING }
        },
        required: ['correctWords', 'incorrectWords', 'feedback']
      }
    }
  });
  return JSON.parse(response.text || "{}");
}

import React, { useState, useRef, useEffect } from 'react';
import { Camera, Volume2, SkipForward, RotateCcw, Send, CheckCircle2, Loader2, List, PenTool, ArrowLeft, X, Plus, ChevronLeft } from 'lucide-react';
import { extractSpellingList, generateSpellingAudio, evaluateSpellingAnswers } from '../geminiService';
import { SpellingSession } from '../types';

interface SpellingPracticeProps {
  onXpEarned: (xp: number) => void;
  onDone: () => void;
  activeSession: SpellingSession | null;
  onSaveSession: (session: SpellingSession | null) => void;
}

function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer, data.byteOffset, data.byteLength / 2);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const SpellingPractice: React.FC<SpellingPracticeProps> = ({ onXpEarned, onDone, activeSession, onSaveSession }) => {
  const [step, setStep] = useState<'UPLOAD_LIST' | 'PRACTICE' | 'UPLOAD_ANSWERS' | 'RESULT'>(activeSession ? 'PRACTICE' : 'UPLOAD_LIST');
  const [sessionData, setSessionData] = useState<SpellingSession | null>(activeSession);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [listImages, setListImages] = useState<string[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const [result, setResult] = useState<any>(null);

  const listInputRef = useRef<HTMLInputElement>(null);
  const answerInputRef = useRef<HTMLInputElement>(null);

  const initAudio = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }
    return audioContextRef.current;
  };

  const playWord = async (word: string) => {
    if (isPlaying) return;
    const ctx = initAudio();
    setIsPlaying(true);
    try {
      const base64 = await generateSpellingAudio(word);
      const audioBytes = decodeBase64(base64);
      const audioBuffer = await decodeAudioData(audioBytes, ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.onended = () => setIsPlaying(false);
      source.start();
    } catch (err: any) {
      console.error("Audio playback error:", err);
      setIsPlaying(false);
    }
  };

  // Trigger audio automatically when step or word changes
  useEffect(() => {
    if (step === 'PRACTICE' && sessionData) {
      const currentWord = sessionData.sessions[sessionData.currentSessionIndex][currentIndex];
      const timer = setTimeout(() => playWord(currentWord), 500);
      return () => clearTimeout(timer);
    }
  }, [step, currentIndex, sessionData?.currentSessionIndex]);

  const handleListPhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setListImages(prev => [...prev, reader.result as string]);
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  };

  const processList = async () => {
    if (listImages.length === 0) return;
    setIsProcessing(true);
    try {
      const base64Array = listImages.map(img => img.split(',')[1]);
      const extracted = await extractSpellingList(base64Array);
      if (extracted.length === 0) throw new Error("No words found");

      // Session logic: split into 20s. 
      // If remaining < 10, merge to last session.
      const sessions: string[][] = [];
      for (let i = 0; i < extracted.length; i += 20) {
        sessions.push(extracted.slice(i, i + 20));
      }
      if (sessions.length > 1) {
        const last = sessions[sessions.length - 1];
        if (last.length < 10) {
          sessions[sessions.length - 2] = [...sessions[sessions.length - 2], ...last];
          sessions.pop();
        }
      }

      const newSession: SpellingSession = {
        allWords: extracted,
        listImages: listImages,
        sessions: sessions,
        currentSessionIndex: 0
      };
      setSessionData(newSession);
      onSaveSession(newSession);
      setStep('PRACTICE');
    } catch (err) {
      alert("Error reading list.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleNextWord = () => {
    const currentSessionWords = sessionData!.sessions[sessionData!.currentSessionIndex];
    if (currentIndex < currentSessionWords.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      setStep('UPLOAD_ANSWERS');
    }
  };

  const handlePrevWord = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  const handleAnswerUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && sessionData) {
      setIsProcessing(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        try {
          const listBase64s = sessionData.listImages.map(img => img.split(',')[1]);
          const currentWords = sessionData.sessions[sessionData.currentSessionIndex];
          const evalResult = await evaluateSpellingAnswers(listBase64s, base64.split(',')[1], currentWords);
          setResult(evalResult);
          onXpEarned(evalResult.correctWords.length * 5); // 5 XP per correct word

          // Move session forward
          const updatedSession = { ...sessionData, currentSessionIndex: sessionData.currentSessionIndex + 1 };
          if (updatedSession.currentSessionIndex >= updatedSession.sessions.length) {
            onSaveSession(null); // All sessions done
          } else {
            onSaveSession(updatedSession);
          }
          setSessionData(updatedSession);
          setStep('RESULT');
        } catch (err) {
          alert("Error evaluating.");
        } finally {
          setIsProcessing(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-8 animate-in fade-in duration-500">
      {step === 'UPLOAD_LIST' && (
        <div className="text-center space-y-6">
          <div className="bg-emerald-100 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto text-emerald-600">
            <List size={40} />
          </div>
          <div className="space-y-2">
            <h2 className="text-3xl font-black text-slate-800">Spelling Practice</h2>
            <p className="text-slate-500">Snap your list. We'll handle chunks of 20 automatically!</p>
          </div>
          <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-6">
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
              {listImages.map((img, i) => (
                <div key={i} className="relative aspect-[3/4] rounded-2xl overflow-hidden border border-slate-200 bg-slate-50 group">
                  <img src={img} alt="List" className="w-full h-full object-cover" />
                  <button onClick={() => setListImages(prev => prev.filter((_, idx) => idx !== i))} className="absolute top-2 right-2 bg-red-500 text-white p-1.5 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-opacity">
                    <X size={14} />
                  </button>
                </div>
              ))}
              <button onClick={() => listInputRef.current?.click()} className="aspect-[3/4] border-4 border-dashed border-slate-100 rounded-2xl flex flex-col items-center justify-center text-slate-400 hover:border-emerald-200 hover:bg-emerald-50/30 transition-all group">
                <Plus size={32} />
                <span className="text-xs font-black mt-2">ADD PHOTO</span>
              </button>
            </div>
            <input type="file" ref={listInputRef} className="hidden" accept="image/*" onChange={handleListPhotoChange} />
            <button disabled={listImages.length === 0 || isProcessing} onClick={processList} className={`w-full py-5 rounded-2xl font-black text-lg shadow-xl transition-all flex items-center justify-center gap-3 ${listImages.length === 0 || isProcessing ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : 'bg-emerald-600 hover:bg-emerald-700 text-white shadow-emerald-100'}`}>
              {isProcessing ? <><Loader2 className="animate-spin" size={20} /> Analyzing...</> : "Start Practice"}
            </button>
          </div>
        </div>
      )}

      {step === 'PRACTICE' && sessionData && (
        <div className="space-y-8">
          <div className="flex justify-between items-center">
            <button onClick={onDone} className="text-slate-400 hover:text-slate-600 font-bold flex items-center gap-2">
              <ArrowLeft size={20} /> QUIT
            </button>
            <div className="flex flex-col items-end">
              <div className="bg-indigo-100 px-4 py-1.5 rounded-full text-indigo-700 font-black text-sm mb-1">
                SESSION {sessionData.currentSessionIndex + 1} OF {sessionData.sessions.length}
              </div>
              <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                WORD {currentIndex + 1} OF {sessionData.sessions[sessionData.currentSessionIndex].length}
              </div>
            </div>
          </div>

          <div className="bg-white p-16 rounded-[40px] border border-slate-200 shadow-xl text-center space-y-8">
            <div className={`w-32 h-32 rounded-full flex items-center justify-center mx-auto shadow-lg transition-all duration-300 ${isPlaying ? 'bg-emerald-500 scale-110 animate-pulse' : 'bg-indigo-600'}`}>
              <Volume2 size={64} className="text-white" />
            </div>
            <div className="space-y-2">
              <h3 className="text-2xl font-black text-slate-800">Listen Carefully</h3>
              <p className="text-slate-500 font-medium italic">Write it down now...</p>
            </div>
            <button onClick={() => playWord(sessionData.sessions[sessionData.currentSessionIndex][currentIndex])} className="text-indigo-600 font-black hover:text-indigo-700 flex items-center justify-center gap-2 mx-auto">
              <RotateCcw size={18} /> REPLAY AUDIO
            </button>
          </div>

          <div className="flex gap-4">
            <button onClick={handlePrevWord} disabled={currentIndex === 0} className="w-1/3 py-6 rounded-3xl font-black text-xl transition-all border-2 border-slate-200 text-slate-400 disabled:opacity-30 enabled:hover:bg-slate-50 enabled:hover:text-slate-600 enabled:border-slate-300 flex items-center justify-center gap-2">
              <ChevronLeft size={24} /> BACK
            </button>
            <button onClick={handleNextWord} className="flex-1 bg-emerald-600 hover:bg-emerald-700 text-white py-6 rounded-3xl font-black text-xl shadow-lg shadow-emerald-100 transition-all flex items-center justify-center gap-3">
              {currentIndex === sessionData.sessions[sessionData.currentSessionIndex].length - 1 ? "FINISH SESSION" : "NEXT WORD"}
              <SkipForward size={24} />
            </button>
          </div>
        </div>
      )}

      {step === 'UPLOAD_ANSWERS' && (
        <div className="text-center space-y-6">
          <div className="bg-indigo-100 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto text-indigo-600"><PenTool size={40} /></div>
          <div className="space-y-2">
            <h2 className="text-3xl font-black text-slate-800">Session Complete!</h2>
            <p className="text-slate-500">Upload a photo of your session {sessionData?.currentSessionIndex! + 1} answers.</p>
          </div>
          <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
            <div onClick={() => answerInputRef.current?.click()} className="border-4 border-dashed border-slate-100 rounded-3xl p-12 text-center hover:border-indigo-200 hover:bg-indigo-50/30 transition-all cursor-pointer">
              <input type="file" ref={answerInputRef} className="hidden" accept="image/*" onChange={handleAnswerUpload} />
              {isProcessing ? <Loader2 className="animate-spin mx-auto text-indigo-600" size={40} /> : <><Camera className="mx-auto mb-4 text-slate-400" size={48} /><p className="text-lg font-bold">Snap Your Page</p></>}
            </div>
          </div>
        </div>
      )}

      {step === 'RESULT' && result && (
        <div className="space-y-8 animate-in zoom-in">
          <div className="text-center space-y-4">
            <CheckCircle2 size={64} className="mx-auto text-emerald-500" />
            <h2 className="text-4xl font-black">Session Marked!</h2>
            <div className="text-6xl font-black text-emerald-600">+{result.correctWords.length * 5} XP</div>
          </div>
          <div className="bg-indigo-50 p-6 rounded-3xl text-center italic">"{result.feedback}"</div>
          <button onClick={onDone} className="w-full bg-slate-800 hover:bg-slate-900 text-white py-5 rounded-2xl font-black">
            {sessionData && sessionData.currentSessionIndex < sessionData.sessions.length ? "CONTINUE NEXT SESSION" : "BACK TO DASHBOARD"}
          </button>
        </div>
      )}
    </div>
  );
};

export default SpellingPractice;

import React, { useState, useEffect } from 'react';
import { AppView, UserStats, EvaluationResult, SpellingSession } from './types';
import { evaluateEssay } from './geminiService';
import Dashboard from './components/Dashboard';
import SubmissionForm from './components/SubmissionForm';
import ResultView from './components/ResultView';
import CoPilotChat from './components/CoPilotChat';
import SpellingPractice from './components/SpellingPractice';
import { BookOpen, LayoutDashboard, Send, Mic } from 'lucide-react';

const XP_PER_LEVEL = 1000;

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.DASHBOARD);
  const [currentTopic, setCurrentTopic] = useState('');
  const [isCoPilotActiveForSubmission, setIsCoPilotActiveForSubmission] = useState(false);

  const [userStats, setUserStats] = useState<UserStats>(() => {
    const saved = localStorage.getItem('essayquest_stats');
    return saved ? JSON.parse(saved) : {
      totalXp: 0,
      level: 1,
      prizesWon: [],
      submissionHistory: [],
      lastScore: 0,
      bonusCharges: 0,
      activeSpellingSession: null
    };
  });

  const [lastEvaluation, setLastEvaluation] = useState<EvaluationResult | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    localStorage.setItem('essayquest_stats', JSON.stringify(userStats));
  }, [userStats]);

  const handleSpellingXp = (xpToAdd: number) => {
    const newTotalXp = userStats.totalXp + xpToAdd;
    const newLevel = Math.floor(newTotalXp / XP_PER_LEVEL) + 1;
    setUserStats(prev => ({ ...prev, totalXp: newTotalXp, level: newLevel }));
  };

  const saveSpellingSession = (session: SpellingSession | null) => {
    setUserStats(prev => ({ ...prev, activeSpellingSession: session }));
  };

  const handleSubmission = async (imageBase64: string) => {
    setIsProcessing(true);
    try {
      const evaluation = await evaluateEssay(imageBase64, currentTopic);
      let scoreXp = evaluation.scores.idea + evaluation.scores.structure + evaluation.scores.content + evaluation.scores.language + evaluation.scores.voice;
      if (isCoPilotActiveForSubmission) scoreXp = Math.floor(scoreXp / 4);

      const newTotalXp = userStats.totalXp + scoreXp;
      const newLevel = Math.floor(newTotalXp / XP_PER_LEVEL) + 1;

      setUserStats(prev => ({
        ...prev,
        totalXp: newTotalXp,
        level: newLevel,
        submissionHistory: [...prev.submissionHistory, `h_${imageBase64.length}`]
      }));

      setLastEvaluation({ ...evaluation, totalXp: scoreXp, isDuplicate: false, bonusApplied: false });
      setView(AppView.RESULT);
    } catch (error) {
      alert("Error grading essay.");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-4xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setView(AppView.DASHBOARD)}>
            <div className="bg-indigo-600 p-2 rounded-xl text-white"><BookOpen size={24} /></div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">EssayQuest</h1>
          </div>
          <nav className="flex gap-4">
            <button onClick={() => setView(AppView.DASHBOARD)} className={`flex items-center gap-1 px-3 py-2 rounded-lg text-sm font-semibold ${view === AppView.DASHBOARD ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500'}`}><LayoutDashboard size={18} /><span className="hidden sm:inline">Dashboard</span></button>
            <button onClick={() => setView(AppView.SPELLING)} className={`flex items-center gap-1 px-3 py-2 rounded-lg text-sm font-semibold ${view === AppView.SPELLING ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500'}`}><Mic size={18} /><span className="hidden sm:inline">Spelling</span></button>
            <button onClick={() => setView(AppView.SUBMIT)} className={`flex items-center gap-1 px-3 py-2 rounded-lg text-sm font-semibold ${view === AppView.SUBMIT ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500'}`}><Send size={18} /><span className="hidden sm:inline">Submit</span></button>
          </nav>
        </div>
      </header>
      <main className="flex-1 max-w-4xl mx-auto px-4 py-8">
        {view === AppView.DASHBOARD && <Dashboard stats={userStats} onStart={() => setView(AppView.SUBMIT)} onStartSpelling={() => setView(AppView.SPELLING)} />}
        {view === AppView.SUBMIT && <SubmissionForm isProcessing={isProcessing} topic={currentTopic} setTopic={setCurrentTopic} onSubmit={handleSubmission} onOpenCoPilot={() => { setIsCoPilotActiveForSubmission(true); setView(AppView.CO_PILOT); }} isCoPilotActive={isCoPilotActiveForSubmission} />}
        {view === AppView.CO_PILOT && <CoPilotChat topic={currentTopic} onBack={() => setView(AppView.SUBMIT)} onSubmitMode={() => setView(AppView.SUBMIT)} />}
        {view === AppView.SPELLING && <SpellingPractice activeSession={userStats.activeSpellingSession} onXpEarned={handleSpellingXp} onSaveSession={saveSpellingSession} onDone={() => setView(AppView.DASHBOARD)} />}
        {view === AppView.RESULT && lastEvaluation && <ResultView result={lastEvaluation} onDone={() => setView(AppView.DASHBOARD)} />}
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RubricScore } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Extracts the assignment topic or instructions from an image.
 */
export async function extractTopicFromImage(imageBase64: string): Promise<string> {
  const model = 'gemini-3-flash-preview';
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: imageBase64,
          },
        },
        {
          text: "Read this homework assignment or essay prompt image. Extract and summarize the main topic or question the student needs to write about. Be concise.",
        },
      ],
    },
  });

  return response.text || "Could not identify topic.";
}

/**
 * Evaluates the handwritten essay image based on the provided topic.
 */
export async function evaluateEssay(imageBase64: string, topic: string): Promise<{
  scores: RubricScore;
  feedback: string;
}> {
  const model = 'gemini-3-pro-preview';

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: imageBase64,
          },
        },
        {
          text: `Evaluate this student's essay submission based on the topic: "${topic}".

          Rubric (0-20 points each):
          A. Relevance & Central Idea (Idea)
          B. Structure & Paragraphing (Structure)
          C. Content & Details / Evidence (Content & Evidence)
          D. Language Clarity & Accuracy (Language)
          E. Voice, Style, and Emotional Impact (Voice)

          Return JSON format.`,
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          scores: {
            type: Type.OBJECT,
            properties: {
              idea: { type: Type.NUMBER },
              structure: { type: Type.NUMBER },
              content: { type: Type.NUMBER },
              language: { type: Type.NUMBER },
              voice: { type: Type.NUMBER },
            },
            required: ['idea', 'structure', 'content', 'language', 'voice'],
          },
          feedback: { type: Type.STRING },
        },
        required: ['scores', 'feedback'],
      },
    },
  });

  return JSON.parse(response.text || '{}');
}

export async function getCoPilotInspiration(
  chatHistory: { role: 'user' | 'ai'; text: string }[],
  currentPrompt: string,
  topic: string
): Promise<string> {
  const model = 'gemini-3-flash-preview';
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...chatHistory.map(msg => ({ text: `${msg.role}: ${msg.text}` })),
        { text: `Topic: ${topic}. Request: ${currentPrompt}` }
      ]
    },
    config: {
      systemInstruction: `Writer co-pilot. Topic: "${topic}". Be concise.`
    }
  });
  return response.text || "I'm sorry, I couldn't help right now.";
}

/**
 * Spelling Services
 */

export async function extractSpellingList(imagesBase64: string[]): Promise<string[]> {
  const model = 'gemini-3-flash-preview';
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...imagesBase64.map(data => ({ inlineData: { mimeType: 'image/jpeg', data } })),
        { text: "Extract all unique spelling words from these images. These can be in English or Chinese. Return only a JSON array of strings." }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: { type: Type.ARRAY, items: { type: Type.STRING } }
    }
  });
  const text = response.text || "[]";
  try {
    return JSON.parse(text);
  } catch (e) {
    console.error("Failed to parse words list:", text);
    return [];
  }
}

export async function generateSpellingAudio(word: string): Promise<string> {
  // Enhanced prompt to ensure clear pronunciation of words/characters
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Say this word clearly: ${word}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' },
        },
      },
    },
  });

  const audioPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
  const base64Audio = audioPart?.inlineData?.data;

  if (!base64Audio) throw new Error("Audio generation failed: No audio data in response.");
  return base64Audio;
}

export async function evaluateSpellingAnswers(
  listImagesBase64: string[],
  answerImageBase64: string,
  words: string[]
): Promise<{
  correctWords: string[];
  incorrectWords: { original: string; student: string }[];
  feedback: string;
}> {
  const model = 'gemini-3-pro-preview';
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...listImagesBase64.map(data => ({ inlineData: { mimeType: 'image/jpeg', data } })),
        { inlineData: { mimeType: 'image/jpeg', data: answerImageBase64 } },
        { text: `The first set of images are the master spelling lists. The final image is the student's handwritten answers. Check spelling accuracy for these specific words: ${words.join(', ')}. Compare the student's handwritten characters or words carefully. Return JSON.` }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          correctWords: { type: Type.ARRAY, items: { type: Type.STRING } },
          incorrectWords: { 
            type: Type.ARRAY, 
            items: { 
              type: Type.OBJECT,
              properties: {
                original: { type: Type.STRING },
                student: { type: Type.STRING }
              }
            }
          },
          feedback: { type: Type.STRING }
        },
        required: ['correctWords', 'incorrectWords', 'feedback']
      }
    }
  });
  return JSON.parse(response.text || "{}");
}

