import React, { useState, useRef, useEffect } from 'react';
import { Camera, Volume2, SkipForward, RotateCcw, Send, CheckCircle2, Loader2, List, PenTool, ArrowLeft, X, Plus, ChevronLeft } from 'lucide-react';
import { extractSpellingList, generateSpellingAudio, evaluateSpellingAnswers } from '../geminiService';
import { SpellingSession } from '../types';

interface SpellingPracticeProps {
  onXpEarned: (xp: number) => void;
  onDone: () => void;
  activeSession: SpellingSession | null;
  onSaveSession: (session: SpellingSession | null) => void;
}

// Helper to decode base64 strings to bytes
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

/**
 * Decodes raw PCM audio data into an AudioBuffer.
 * Gemini TTS returns raw PCM (no header).
 */
async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer, data.byteOffset, data.byteLength / 2);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const SpellingPractice: React.FC<SpellingPracticeProps> = ({ onXpEarned, onDone, activeSession, onSaveSession }) => {
  const [step, setStep] = useState<'UPLOAD_LIST' | 'PRACTICE' | 'UPLOAD_ANSWERS' | 'RESULT'>(activeSession ? 'PRACTICE' : 'UPLOAD_LIST');
  const [sessionData, setSessionData] = useState<SpellingSession | null>(activeSession);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [result, setResult] = useState<any>(null);

  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const listInputRef = useRef<HTMLInputElement>(null);
  const answerInputRef = useRef<HTMLInputElement>(null);

  // Initialize the audio context on user interaction
  const initAudio = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }
    return audioContextRef.current;
  };

  // Stops currently playing word audio
  const stopAudio = () => {
    if (currentSourceRef.current) {
      try {
        currentSourceRef.current.stop();
      } catch (e) {}
      currentSourceRef.current = null;
    }
    setIsPlaying(false);
  };

  /**
   * Handles the upload of spelling list photos and extracts words.
   */
  const handleListUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;

    setIsProcessing(true);
    try {
      const readers = files.map(file => {
        return new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
      });

      const images = await Promise.all(readers);
      const base64s = images.map(img => img.split(',')[1]);
      const words = await extractSpellingList(base64s);

      if (words.length === 0) {
        alert("No words found. Please try a clearer photo of your spelling list.");
        return;
      }

      // Group words into sessions of 10 for better pacing
      const sessions: string[][] = [];
      for (let i = 0; i < words.length; i += 10) {
        sessions.push(words.slice(i, i + 10));
      }

      const newSession: SpellingSession = {
        allWords: words,
        listImages: base64s,
        sessions,
        currentSessionIndex: 0
      };

      setSessionData(newSession);
      onSaveSession(newSession);
      setStep('PRACTICE');
    } catch (err) {
      console.error(err);
      alert("Error processing images.");
    } finally {
      setIsProcessing(false);
    }
  };

  /**
   * Generates and plays audio for a specific word.
   */
  const playWord = async (word: string) => {
    if (isPlaying) stopAudio();
    setIsPlaying(true);
    const ctx = initAudio();

    try {
      const base64 = await generateSpellingAudio(word);
      const audioBuffer = await decodeAudioData(decodeBase64(base64), ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.onended = () => setIsPlaying(false);
      currentSourceRef.current = source;
      source.start();
    } catch (err) {
      console.error(err);
      setIsPlaying(false);
    }
  };

  /**
   * Handles the upload of handwritten answers and triggers evaluation.
   */
  const handleAnswerUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !sessionData) return;

    setIsProcessing(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      try {
        const answerBase64 = (reader.result as string).split(',')[1];
        const currentWords = sessionData.sessions[sessionData.currentSessionIndex];
        const evaluation = await evaluateSpellingAnswers(
          sessionData.listImages,
          answerBase64,
          currentWords
        );
        setResult(evaluation);
        setStep('RESULT');

        // Reward 50 XP per correct word
        const xp = evaluation.correctWords.length * 50;
        onXpEarned(xp);
      } catch (err) {
        console.error(err);
        alert("Error evaluating answers.");
      } finally {
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  /**
   * Moves to the next session of words or finishes the practice.
   */
  const nextSession = () => {
    if (!sessionData) return;
    const nextIdx = sessionData.currentSessionIndex + 1;
    if (nextIdx < sessionData.sessions.length) {
      const updated = { ...sessionData, currentSessionIndex: nextIdx };
      setSessionData(updated);
      onSaveSession(updated);
      setCurrentIndex(0);
      setStep('PRACTICE');
      setResult(null);
    } else {
      onSaveSession(null);
      onDone();
    }
  };

  // Rendering logic for different steps
  if (step === 'UPLOAD_LIST') {
    return (
      <div className="max-w-xl mx-auto space-y-8 animate-in fade-in duration-500">
        <div className="text-center space-y-3">
          <div className="bg-emerald-100 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto text-emerald-600">
            <List size={32} />
          </div>
          <h2 className="text-3xl font-black text-slate-800">Spelling Practice</h2>
          <p className="text-slate-500 text-sm">Upload photos of your spelling list (English or Chinese).</p>
        </div>

        <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
          <button 
            disabled={isProcessing}
            onClick={() => listInputRef.current?.click()}
            className="w-full border-4 border-dashed border-slate-100 rounded-3xl p-12 text-center hover:border-emerald-200 hover:bg-emerald-50/30 transition-all cursor-pointer group flex flex-col items-center"
          >
            <input type="file" ref={listInputRef} className="hidden" accept="image/*" multiple onChange={handleListUpload} />
            <div className="bg-slate-50 w-20 h-20 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 group-hover:bg-white transition-transform shadow-sm">
              {isProcessing ? <Loader2 className="animate-spin text-emerald-600" size={40} /> : <Camera className="text-slate-400 group-hover:text-emerald-600" size={40} />}
            </div>
            <p className="text-lg font-bold text-slate-700">{isProcessing ? "Reading Word List..." : "Snap Word Lists"}</p>
          </button>
        </div>
      </div>
    );
  }

  if (step === 'PRACTICE' && sessionData) {
    const currentWords = sessionData.sessions[sessionData.currentSessionIndex];
    const word = currentWords[currentIndex];

    return (
      <div className="max-w-xl mx-auto space-y-8 animate-in slide-in-from-bottom duration-500">
        <div className="flex items-center justify-between">
          <button onClick={onDone} className="text-slate-400 font-bold hover:text-slate-600 flex items-center gap-1">
            <ArrowLeft size={18} /> BACK
          </button>
          <div className="text-sm font-black text-indigo-600 bg-indigo-50 px-4 py-1 rounded-full">
            SESSION {sessionData.currentSessionIndex + 1} / {sessionData.sessions.length}
          </div>
        </div>

        <div className="bg-white p-12 rounded-[2.5rem] border border-slate-200 shadow-xl shadow-slate-100 text-center space-y-10">
          <div className="space-y-2">
             <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Listen Carefully</p>
             <h3 className="text-xl font-bold text-slate-800">Word {currentIndex + 1} of {currentWords.length}</h3>
          </div>

          <button 
            onClick={() => playWord(word)}
            className={`w-32 h-32 rounded-full mx-auto flex items-center justify-center transition-all transform active:scale-95 shadow-lg
              ${isPlaying ? 'bg-indigo-600 text-white animate-pulse' : 'bg-indigo-50 text-indigo-600 hover:bg-indigo-100'}
            `}
          >
            <Volume2 size={48} />
          </button>

          <div className="flex flex-col sm:flex-row gap-4">
            <button 
              onClick={() => playWord(word)}
              className="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-700 py-4 rounded-2xl font-bold flex items-center justify-center gap-2"
            >
              <RotateCcw size={18} /> REPEAT
            </button>

            {currentIndex < currentWords.length - 1 ? (
              <button 
                onClick={() => { stopAudio(); setCurrentIndex(currentIndex + 1); }}
                className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white py-4 rounded-2xl font-bold flex items-center justify-center gap-2"
              >
                NEXT WORD <SkipForward size={18} />
              </button>
            ) : (
              <button 
                onClick={() => setStep('UPLOAD_ANSWERS')}
                className="flex-1 bg-emerald-600 hover:bg-emerald-700 text-white py-4 rounded-2xl font-bold flex items-center justify-center gap-2"
              >
                SUBMIT PHOTO <Send size={18} />
              </button>
            )}
          </div>
        </div>

        <div className="flex justify-center gap-2">
          {currentWords.map((_, i) => (
            <div key={i} className={`h-2 rounded-full transition-all ${i === currentIndex ? 'w-8 bg-indigo-600' : i < currentIndex ? 'w-2 bg-indigo-200' : 'w-2 bg-slate-200'}`} />
          ))}
        </div>
      </div>
    );
  }

  if (step === 'UPLOAD_ANSWERS') {
    return (
      <div className="max-w-xl mx-auto space-y-8 animate-in zoom-in duration-500">
        <div className="text-center space-y-3">
          <div className="bg-amber-100 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto text-amber-600">
            <PenTool size={32} />
          </div>
          <h2 className="text-3xl font-black text-slate-800">Done Writing?</h2>
          <p className="text-slate-500 text-sm">Snap a photo of your handwritten spelling answers.</p>
        </div>

        <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
           <button 
            disabled={isProcessing}
            onClick={() => answerInputRef.current?.click()}
            className="w-full border-4 border-dashed border-slate-100 rounded-3xl p-12 text-center hover:border-amber-200 hover:bg-amber-50/30 transition-all cursor-pointer group flex flex-col items-center"
          >
            <input type="file" ref={answerInputRef} className="hidden" accept="image/*" capture="environment" onChange={handleAnswerUpload} />
            <div className="bg-slate-50 w-20 h-20 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 group-hover:bg-white transition-transform shadow-sm">
              {isProcessing ? <Loader2 className="animate-spin text-amber-600" size={40} /> : <Camera className="text-slate-400 group-hover:text-amber-600" size={40} />}
            </div>
            <p className="text-lg font-bold text-slate-700">{isProcessing ? "Checking Your Work..." : "Scan Answers"}</p>
          </button>
        </div>

        <button onClick={() => setStep('PRACTICE')} className="w-full text-slate-400 font-bold hover:text-slate-600">
          ← Back to Practice
        </button>
      </div>
    );
  }

  if (step === 'RESULT' && result) {
    const xp = result.correctWords.length * 50;
    return (
      <div className="max-w-xl mx-auto space-y-8 animate-in slide-in-from-bottom duration-500">
        <div className="bg-emerald-600 p-8 rounded-[2.5rem] text-white text-center shadow-xl shadow-emerald-100">
          <div className="bg-white/20 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4">
            <CheckCircle2 size={32} />
          </div>
          <h2 className="text-3xl font-black mb-2">Great Work!</h2>
          <p className="text-emerald-50 text-7xl font-black tabular-nums">+{xp} XP</p>
          <div className="mt-6 flex justify-center gap-4">
             <div className="bg-white/10 px-4 py-2 rounded-xl border border-white/20">
                <p className="text-xs font-bold opacity-70">CORRECT</p>
                <p className="text-2xl font-black">{result.correctWords.length}</p>
             </div>
             <div className="bg-white/10 px-4 py-2 rounded-xl border border-white/20">
                <p className="text-xs font-bold opacity-70">INCORRECT</p>
                <p className="text-2xl font-black">{result.incorrectWords.length}</p>
             </div>
          </div>
        </div>

        <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-6">
          {result.incorrectWords.length > 0 && (
            <div className="space-y-3">
              <h3 className="font-bold text-slate-800">Words to Review:</h3>
              <div className="space-y-2">
                {result.incorrectWords.map((item: any, i: number) => (
                  <div key={i} className="flex items-center justify-between p-3 bg-red-50 rounded-xl border border-red-100">
                    <span className="font-bold text-red-900">{item.original}</span>
                    <span className="text-xs font-medium text-red-400">You wrote: {item.student}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="space-y-2">
            <h3 className="font-bold text-slate-800">Teacher's Note:</h3>
            <p className="text-slate-600 text-sm leading-relaxed">{result.feedback}</p>
          </div>

          <button 
            onClick={nextSession}
            className="w-full bg-slate-800 hover:bg-slate-900 text-white font-black py-5 rounded-2xl flex items-center justify-center gap-2 shadow-lg"
          >
            {sessionData && sessionData.currentSessionIndex < sessionData.sessions.length - 1 ? 'NEXT SESSION' : 'FINISH PRACTICE'}
          </button>
        </div>
      </div>
    );
  }

  return null;
};

