import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RubricScore } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Extracts the assignment topic or instructions from an image.
 */
export async function extractTopicFromImage(imageBase64: string): Promise<string> {
  const model = 'gemini-3-flash-preview';
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: imageBase64,
          },
        },
        {
          text: "Read this homework assignment or essay prompt image. Extract and summarize the main topic or question the student needs to write about. Be concise.",
        },
      ],
    },
  });

  return response.text || "Could not identify topic.";
}

/**
 * Evaluates the handwritten essay image based on the provided topic.
 */
export async function evaluateEssay(imageBase64: string, topic: string): Promise<{
  scores: RubricScore;
  feedback: string;
}> {
  const model = 'gemini-3-pro-preview';

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: imageBase64,
          },
        },
        {
          text: `Evaluate this student's essay submission based on the topic: "${topic}".

          STRICT REQUIREMENTS: 
          1. CONTENT TYPE CHECK: Check if the work is an ESSAY or COMPOSITION. If the image contains something else (e.g., math problems, science diagrams, random drawings, or a list of unrelated words that do not form a story or essay), you MUST give a score of 0 for EVERY category.
          2. HANDWRITING CHECK: Check if the essay in the image is HANDWRITTEN. If the text is TYPED (digital font, printed, or computer-generated text), you MUST give a score of 0 for EVERY category.
          3. If the work IS a handwritten essay/composition, evaluate it honestly using the rubric.

          Rubric (0-20 points each):
          A. Relevance & Central Idea (Idea)
          B. Structure & Paragraphing (Structure)
          C. Content & Details / Evidence (Content & Evidence)
          D. Language Clarity & Accuracy (Language)
          E. Voice, Style, and Emotional Impact (Voice)

          Return the response in JSON format. If you give 0 points due to requirements 1 or 2, explain this clearly in the feedback.`,
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          scores: {
            type: Type.OBJECT,
            properties: {
              idea: { type: Type.NUMBER },
              structure: { type: Type.NUMBER },
              content: { type: Type.NUMBER },
              language: { type: Type.NUMBER },
              voice: { type: Type.NUMBER },
            },
            required: ['idea', 'structure', 'content', 'language', 'voice'],
          },
          feedback: { type: Type.STRING },
        },
        required: ['scores', 'feedback'],
      },
    },
  });

  try {
    const result = JSON.parse(response.text || '{}');
    return result;
  } catch (e) {
    console.error("Failed to parse evaluation response", e);
    throw new Error("Evaluation failed. Please try again.");
  }
}

export async function getCoPilotInspiration(
  chatHistory: { role: 'user' | 'ai'; text: string }[],
  currentPrompt: string,
  topic: string
): Promise<string> {
  const model = 'gemini-3-flash-preview';

  const historyParts = chatHistory.map(msg => ({
    text: `${msg.role === 'user' ? 'Student' : 'Assistant'}: ${msg.text}`
  }));

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...historyParts,
        { text: `Topic of the essay: ${topic}. Student's current request: ${currentPrompt}` }
      ]
    },
    config: {
      systemInstruction: `You are a creative writing co-pilot for a student aged 11-16. 
      The essay topic is: "${topic}".
      Your goal is to give inspiration, themes, metaphors, or starting questions based on this topic. 

      STRICT RULES:
      1. Keep your responses CONCISE and SHORT (aim for under 100 words).
      2. Do not use complex language; be punchy and encouraging.
      3. Use simple Markdown formatting (bullet points, bold text) to make it easy to read.
      4. Do not give the student direct answers or write the essay for them.
      5. If they ask for an answer or a specific paragraph, politely refuse and instead suggest an idea for them to explore.`
    }
  });

  return response.text || "I'm sorry, I couldn't generate an inspiration right now.";
}

/**
 * Spelling Services
 */

export async function extractSpellingList(imagesBase64: string[]): Promise<string[]> {
  const model = 'gemini-3-flash-preview';

  const imageParts = imagesBase64.map(data => ({
    inlineData: { mimeType: 'image/jpeg', data }
  }));

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...imageParts,
        { text: "Extract all the unique spelling words from these images. They could be English words or Chinese characters. Return only the list of words/characters as a JSON array of strings. Do not include duplicates." }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: { type: Type.STRING }
      }
    }
  });

  return JSON.parse(response.text || "[]");
}

export async function generateSpellingAudio(word: string): Promise<string> {
  // Use a very direct prompt to prevent the model from adding text preambles
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Say clearly: ${word}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' },
        },
      },
    },
  });

  // Robustly find the audio part in the response
  const audioPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
  const base64Audio = audioPart?.inlineData?.data;

  if (!base64Audio) {
    throw new Error("Audio generation failed: The model did not return audio data.");
  }
  return base64Audio;
}

export async function evaluateSpellingAnswers(
  listImagesBase64: string[],
  answerImageBase64: string,
  words: string[]
): Promise<{
  correctWords: string[];
  incorrectWords: { original: string; student: string }[];
  feedback: string;
}> {
  const model = 'gemini-3-pro-preview';

  const masterListParts = listImagesBase64.map(data => ({
    inlineData: { mimeType: 'image/jpeg', data }
  }));

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...masterListParts,
        { inlineData: { mimeType: 'image/jpeg', data: answerImageBase64 } },
        { 
          text: `The first set of images are the master spelling lists (can be English or Chinese). The final image is the student's handwritten answers. 
          Check the spelling accuracy for each of these words: ${words.join(', ')}. 
          Be strict. Read the student's handwriting carefully. 
          Return a JSON object with:
          1. correctWords: Array of strings that the student spelled exactly right.
          2. incorrectWords: Array of objects with 'original' and 'student' (what the student wrote).
          3. feedback: A short encouraging message.`
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          correctWords: { type: Type.ARRAY, items: { type: Type.STRING } },
          incorrectWords: { 
            type: Type.ARRAY, 
            items: { 
              type: Type.OBJECT,
              properties: {
                original: { type: Type.STRING },
                student: { type: Type.STRING }
              }
            }
          },
          feedback: { type: Type.STRING }
        },
        required: ['correctWords', 'incorrectWords', 'feedback']
      }
    }
  });

  return JSON.parse(response.text || "{}");
}

import React, { useState, useEffect } from 'react';
import { AppView, UserStats, EvaluationResult, SpellingSession } from './types';
import { evaluateEssay } from './geminiService';
import Dashboard from './components/Dashboard';
import SubmissionForm from './components/SubmissionForm';
import ResultView from './components/ResultView';
import CoPilotChat from './components/CoPilotChat';
import SpellingPractice from './components/SpellingPractice';
import { BookOpen, LayoutDashboard, Send, Mic } from 'lucide-react';

const XP_PER_LEVEL = 1000;

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.DASHBOARD);
  const [currentTopic, setCurrentTopic] = useState('');
  const [isCoPilotActiveForSubmission, setIsCoPilotActiveForSubmission] = useState(false);

  const [userStats, setUserStats] = useState<UserStats>(() => {
    const saved = localStorage.getItem('essayquest_stats');
    return saved ? JSON.parse(saved) : {
      totalXp: 0,
      level: 1,
      prizesWon: [],
      submissionHistory: [],
      lastScore: 0,
      bonusCharges: 0,
      activeSpellingSession: null
    };
  });

  const [lastEvaluation, setLastEvaluation] = useState<EvaluationResult | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    localStorage.setItem('essayquest_stats', JSON.stringify(userStats));
  }, [userStats]);

  const generatePrizeCode = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let code = '';
    for (let i = 0; i < 12; i++) {
      code += chars.charAt(Math.floor(Math.random() * chars.length));
      if ((i + 1) % 4 === 0 && i !== 11) code += '-';
    }
    return code;
  };

  const handleSpellingXp = (correctCount: number) => {
    const xpToAdd = correctCount * 5; // 5 XP per word
    const newTotalXp = userStats.totalXp + xpToAdd;
    const newLevel = Math.floor(newTotalXp / XP_PER_LEVEL) + 1;

    setUserStats(prev => ({
      ...prev,
      totalXp: newTotalXp,
      level: newLevel
    }));
  };

  const handleSaveSpellingSession = (session: SpellingSession | null) => {
    setUserStats(prev => ({ ...prev, activeSpellingSession: session }));
  };

  const handleSubmission = async (imageBase64: string) => {
    setIsProcessing(true);
    try {
      const contentHash = `hash_${imageBase64.length}`;
      const isDuplicate = userStats.submissionHistory.includes(contentHash);

      const evaluation = await evaluateEssay(imageBase64, currentTopic);

      let scoreXp = evaluation.scores.idea + evaluation.scores.structure + evaluation.scores.content + evaluation.scores.language + evaluation.scores.voice;

      if (isCoPilotActiveForSubmission) {
        scoreXp = Math.floor(scoreXp / 4);
      }

      const isFirstSubmission = userStats.submissionHistory.length === 0;
      if (isFirstSubmission && scoreXp < 50 && scoreXp > 0) scoreXp = 50;
      if (isDuplicate) scoreXp = 0;

      let finalXp = scoreXp;
      const bonusApplied = userStats.bonusCharges > 0 && !isDuplicate && scoreXp > 0;
      if (bonusApplied) {
        finalXp = Math.floor(finalXp * 1.1);
      }

      const newTotalXp = userStats.totalXp + finalXp;
      const oldLevel = userStats.level;
      const newLevel = Math.floor(newTotalXp / XP_PER_LEVEL) + 1;

      let newPrizes = [...userStats.prizesWon];
      if (Math.floor(newLevel / 10) > Math.floor(oldLevel / 10)) {
        newPrizes.push(generatePrizeCode());
      }

      let newBonusCharges = userStats.bonusCharges > 0 ? userStats.bonusCharges - 1 : 0;
      if (!isDuplicate && !isFirstSubmission && scoreXp > userStats.lastScore && scoreXp > 0) {
        newBonusCharges = 2;
      }

      setUserStats(prev => ({
        ...prev,
        totalXp: newTotalXp,
        level: newLevel,
        prizesWon: newPrizes,
        submissionHistory: isDuplicate ? prev.submissionHistory : [...prev.submissionHistory, contentHash],
        lastScore: isDuplicate ? prev.lastScore : scoreXp,
        bonusCharges: newBonusCharges
      }));

      setLastEvaluation({
        ...evaluation,
        totalXp: finalXp,
        isDuplicate,
        bonusApplied
      });
      setView(AppView.RESULT);
      setCurrentTopic('');
      setIsCoPilotActiveForSubmission(false);
    } catch (error) {
      alert("Error processing your homework. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-4xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setView(AppView.DASHBOARD)}>
            <div className="bg-indigo-600 p-2 rounded-xl text-white">
              <BookOpen size={24} />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">EssayQuest</h1>
          </div>

          <nav className="flex gap-4">
            <button 
              onClick={() => setView(AppView.DASHBOARD)}
              className={`flex items-center gap-1 px-3 py-2 rounded-lg text-sm font-semibold transition-all ${view === AppView.DASHBOARD ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500 hover:bg-slate-100'}`}
            >
              <LayoutDashboard size={18} />
              <span className="hidden sm:inline">Dashboard</span>
            </button>
            <button 
              onClick={() => setView(AppView.SPELLING)}
              className={`flex items-center gap-1 px-3 py-2 rounded-lg text-sm font-semibold transition-all ${view === AppView.SPELLING ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500 hover:bg-slate-100'}`}
            >
              <Mic size={18} />
              <span className="hidden sm:inline">Spelling</span>
            </button>
            <button 
              onClick={() => {
                setCurrentTopic('');
                setIsCoPilotActiveForSubmission(false);
                setView(AppView.SUBMIT);
              }}
              className={`flex items-center gap-1 px-3 py-2 rounded-lg text-sm font-semibold transition-all ${view === AppView.SUBMIT ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500 hover:bg-slate-100'}`}
            >
              <Send size={18} />
              <span className="hidden sm:inline">Submit</span>
            </button>
          </nav>
        </div>
      </header>

      <main className="flex-1 w-full max-w-4xl mx-auto px-4 py-8">
        {view === AppView.DASHBOARD && (
          <Dashboard 
            stats={userStats} 
            onStart={() => setView(AppView.SUBMIT)} 
            onStartSpelling={() => setView(AppView.SPELLING)} 
          />
        )}

        {view === AppView.SUBMIT && (
          <SubmissionForm 
            isProcessing={isProcessing} 
            topic={currentTopic}
            setTopic={setCurrentTopic}
            onSubmit={handleSubmission} 
            onOpenCoPilot={() => {
              setIsCoPilotActiveForSubmission(true);
              setView(AppView.CO_PILOT);
            }}
            isCoPilotActive={isCoPilotActiveForSubmission}
          />
        )}

        {view === AppView.CO_PILOT && (
          <CoPilotChat 
            topic={currentTopic}
            onBack={() => setView(AppView.SUBMIT)} 
            onSubmitMode={() => setView(AppView.SUBMIT)}
          />
        )}

        {view === AppView.SPELLING && (
          <SpellingPractice 
            onXpEarned={handleSpellingXp}
            onDone={() => setView(AppView.DASHBOARD)}
            activeSession={userStats.activeSpellingSession}
            onSaveSession={handleSaveSpellingSession}
          />
        )}

        {view === AppView.RESULT && lastEvaluation && (
          <ResultView 
            result={lastEvaluation} 
            onDone={() => setView(AppView.DASHBOARD)} 
          />
        )}
      </main>

      <footer className="py-8 text-center text-slate-400 text-sm">
        <p>© 2024 EssayQuest • Evaluation by AI</p>
      </footer>
    </div>
  );
};

